:root {
  --bg: #0d1711;
  --bg2: #142019;
  --panel: #1b2a21;
  --panel-2: #24382b;
  --panel-3: #2e4534;
  --line: rgba(255, 246, 223, 0.12);
  --cream: #fff6df;
  --muted: #a7bcae;
  --gold: #ffcf5c;
  --gold-deep: #dfa32d;
  --green: #8ce06b;
  --green-deep: #4e9c3a;
  --red: #ff5c68;
  --blue: #61b8ff;
  --shadow: 0 18px 40px rgba(0, 0, 0, 0.42);
  --radius: 18px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
}

body {
  background:
    radial-gradient(1200px 700px at 50% -20%, #22392a 0%, transparent 60%),
    linear-gradient(160deg, #0b130e 0%, #101d15 55%, #0a120d 100%);
  color: var(--cream);
  font-family: "Trebuchet MS", "Segoe UI", "Avenir Next", system-ui, sans-serif;
  overflow: hidden;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}

#app {
  display: flex;
  flex-direction: column;
  height: 100dvh;
  width: 100%;
  max-width: 1500px;
  margin: 0 auto;
  padding: 10px clamp(8px, 1.6vw, 20px) max(8px, env(safe-area-inset-bottom));
  gap: 8px;
}

/* ---------- Top bar ---------- */

.topbar {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 6px 8px 6px 6px;
  flex: 0 0 auto;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.brand-mark {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  background: linear-gradient(160deg, #2c4734, #192a20);
  border: 1px solid rgba(255, 207, 92, 0.28);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.08), 0 4px 12px rgba(0,0,0,.3);
  flex: 0 0 auto;
}

.brand-copy h1 {
  margin: 0;
  font-size: clamp(17px, 2.1vw, 24px);
  letter-spacing: 0.055em;
  font-weight: 900;
  color: var(--cream);
  text-shadow: 0 2px 0 rgba(0, 0, 0, 0.35);
  white-space: nowrap;
}

.brand-copy p {
  margin: 1px 0 0;
  font-size: clamp(8px, 0.9vw, 10px);
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--gold);
  opacity: 0.9;
  white-space: nowrap;
}

.hud {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-left: auto;
}

.stat {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 38px;
  padding: 0 12px 0 9px;
  border-radius: 12px;
  background: linear-gradient(180deg, var(--panel-2), var(--panel));
  border: 1px solid var(--line);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.05), 0 3px 8px rgba(0,0,0,.18);
  font-size: 15px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.stat .ic { width: 18px; height: 18px; flex: 0 0 auto; }
.stat b { font-weight: 800; letter-spacing: 0.01em; }
.stat .muted { color: var(--muted); font-size: 11px; font-weight: 700; }
.stat.cash b { color: var(--gold); }
.stat.round-stat b { color: #c6f0a8; }

.stat.flash-down b { animation: statFlash 0.4s ease; }

@keyframes statFlash {
  0% { color: #fff; transform: scale(1.18); }
  100% { transform: scale(1); }
}

.controls {
  display: flex;
  gap: 6px;
  margin-left: 4px;
}

.icon-btn {
  width: 38px;
  height: 38px;
  border-radius: 11px;
  border: 1px solid var(--line);
  background: linear-gradient(180deg, var(--panel-2), var(--panel));
  color: var(--cream);
  display: grid;
  place-items: center;
  cursor: pointer;
  transition: transform .12s ease, background .18s ease, border-color .18s ease;
  padding: 0;
}

.icon-btn svg { width: 18px; height: 18px; }
.icon-btn.wide { width: auto; min-width: 44px; padding: 0 9px; font-weight: 900; font-size: 13px; color: var(--gold); }
.icon-btn:hover { background: var(--panel-3); border-color: rgba(255,207,92,.35); }
.icon-btn:active { transform: scale(0.93); }
.icon-btn.on { border-color: rgba(255,207,92,.6); color: var(--gold); box-shadow: 0 0 0 2px rgba(255,207,92,.14); }
.icon-btn.off .sound-wave { display: none; }
.icon-btn.muted { color: #7b8c7f; }

/* ---------- Stage ---------- */

.stage-wrap {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.stage {
  position: relative;
  width: 100%;
  max-width: 1400px;
  aspect-ratio: 16 / 9;
  max-height: 100%;
  border-radius: clamp(12px, 1.6vw, 22px);
  overflow: hidden;
  background: #6cae4b;
  box-shadow: 0 22px 60px rgba(0,0,0,.5), 0 0 0 1px rgba(255, 248, 227, 0.1), inset 0 0 0 1px rgba(0,0,0,.15);
  touch-action: none;
}

#game {
  display: block;
  width: 100%;
  height: 100%;
  cursor: crosshair;
  touch-action: none;
}

.stage-top {
  position: absolute;
  top: 10px;
  left: 12px;
  right: 12px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  pointer-events: none;
  z-index: 5;
}

.round-pill {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 7px 12px 8px;
  min-width: 118px;
  border-radius: 12px;
  background: rgba(17, 29, 22, 0.78);
  border: 1px solid rgba(255, 246, 223, 0.16);
  backdrop-filter: blur(8px);
  box-shadow: 0 6px 18px rgba(0,0,0,.28);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #eaf5e4;
}

.progress {
  width: 100%;
  height: 4px;
  border-radius: 4px;
  background: rgba(255,255,255,.14);
  overflow: hidden;
}

.progress i {
  display: block;
  height: 100%;
  width: 0%;
  border-radius: inherit;
  background: linear-gradient(90deg, #ffd45f, #ff9d4d);
  transition: width .18s linear;
}

.stage-actions { display: flex; align-items: center; gap: 7px; pointer-events: auto; }

.auto-toggle {
  display: flex;
  align-items: center;
  gap: 5px;
  height: 36px;
  padding: 0 9px;
  border-radius: 10px;
  background: rgba(17, 29, 22, 0.72);
  border: 1px solid rgba(255, 246, 223, 0.15);
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  cursor: pointer;
  backdrop-filter: blur(8px);
}

.auto-toggle input {
  appearance: none;
  width: 26px;
  height: 15px;
  border-radius: 9px;
  background: #3a4d3f;
  position: relative;
  cursor: pointer;
  transition: background .18s;
  margin: 0;
}

.auto-toggle input::after {
  content: "";
  position: absolute;
  left: 2px;
  top: 2px;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: #cfe0d2;
  transition: left .18s, background .18s;
}

.auto-toggle input:checked { background: var(--green-deep); }
.auto-toggle input:checked::after { left: 13px; background: #fff; }

.start-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 38px;
  padding: 0 15px 0 10px;
  border: 0;
  border-radius: 11px;
  background: linear-gradient(180deg, #ffd766, #f0a92f);
  color: #3c2a07;
  font-family: inherit;
  font-size: 12.5px;
  font-weight: 900;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow: 0 4px 0 #a86e13, 0 8px 18px rgba(0,0,0,.3), inset 0 1px 0 rgba(255,255,255,.6);
  transition: transform .1s ease, filter .15s ease;
  white-space: nowrap;
}

.start-btn svg { width: 17px; height: 17px; }
.start-btn:hover { filter: brightness(1.07); }
.start-btn:active { transform: translateY(2px); box-shadow: 0 2px 0 #a86e13, 0 5px 12px rgba(0,0,0,.3); }
.start-btn:disabled { filter: grayscale(.65) brightness(.7); cursor: default; transform: none; box-shadow: 0 4px 0 #5d4a26; }
.start-btn.pulse { animation: startPulse 1.8s ease-in-out infinite; }

@keyframes startPulse {
  0%, 100% { box-shadow: 0 4px 0 #a86e13, 0 8px 18px rgba(0,0,0,.3), 0 0 0 0 rgba(255,207,92,.35); }
  50% { box-shadow: 0 4px 0 #a86e13, 0 8px 18px rgba(0,0,0,.3), 0 0 0 9px rgba(255,207,92,0); }
}

.place-hint {
  position: absolute;
  left: 50%;
  bottom: 8%;
  transform: translateX(-50%);
  padding: 8px 15px;
  border-radius: 999px;
  background: rgba(17, 29, 22, 0.88);
  border: 1px solid rgba(255, 207, 92, 0.45);
  color: var(--cream);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: .02em;
  white-space: nowrap;
  pointer-events: none;
  backdrop-filter: blur(8px);
  box-shadow: 0 6px 18px rgba(0,0,0,.3);
  z-index: 6;
}

.toast {
  position: absolute;
  top: 62px;
  left: 50%;
  transform: translate(-50%, -10px);
  padding: 8px 16px;
  border-radius: 11px;
  background: rgba(17, 29, 22, 0.92);
  border: 1px solid rgba(255, 246, 223, 0.18);
  color: var(--cream);
  font-size: 12.5px;
  font-weight: 800;
  opacity: 0;
  pointer-events: none;
  transition: opacity .2s ease, transform .2s ease;
  z-index: 8;
  max-width: 80%;
  text-align: center;
  box-shadow: 0 8px 24px rgba(0,0,0,.35);
}

.toast.show { opacity: 1; transform: translate(-50%, 0); }
.toast.bad { border-color: rgba(255, 92, 104, 0.55); color: #ffc6ca; }
.toast.good { border-color: rgba(140, 224, 107, 0.55); color: #dcffcc; }

.watermark {
  position: absolute;
  right: 15px;
  bottom: 10px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.28em;
  color: rgba(255, 248, 227, 0.28);
  pointer-events: none;
  z-index: 2;
}

/* ---------- Inspector ---------- */

.inspector {
  position: absolute;
  right: 12px;
  bottom: 12px;
  width: 248px;
  border-radius: 15px;
  background: linear-gradient(180deg, rgba(29, 44, 34, 0.97), rgba(19, 31, 23, 0.97));
  border: 1px solid rgba(255, 246, 223, 0.16);
  box-shadow: 0 18px 40px rgba(0,0,0,.45);
  padding: 11px 12px 12px;
  z-index: 7;
  backdrop-filter: blur(10px);
  animation: inspectorIn .16s ease-out;
}

@keyframes inspectorIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.ins-head { display: flex; align-items: center; gap: 9px; }
.ins-icon {
  width: 42px;
  height: 42px;
  border-radius: 10px;
  background: rgba(0,0,0,.22);
  border: 1px solid rgba(255,255,255,.07);
  flex: 0 0 auto;
}
.ins-title { min-width: 0; flex: 1; }
.ins-title h3 { margin: 0; font-size: 14.5px; font-weight: 900; letter-spacing: .015em; }
.ins-title p { margin: 2px 0 0; font-size: 10.5px; color: var(--muted); font-weight: 700; }

.ins-close {
  border: 0;
  background: rgba(255,255,255,.07);
  color: #cddfd1;
  width: 24px;
  height: 24px;
  border-radius: 7px;
  font-size: 15px;
  line-height: 1;
  cursor: pointer;
  display: grid;
  place-items: center;
}
.ins-close:hover { background: rgba(255,255,255,.14); }

.ins-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 5px;
  margin: 10px 0;
}

.ins-stat {
  background: rgba(0,0,0,.2);
  border: 1px solid rgba(255,255,255,.06);
  border-radius: 8px;
  padding: 5px 6px;
}
.ins-stat span { display: block; font-size: 8px; letter-spacing: .1em; text-transform: uppercase; color: var(--muted); font-weight: 800; }
.ins-stat b { font-size: 12.5px; color: #eef9e9; font-variant-numeric: tabular-nums; }

.ins-target {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  border: 1px solid rgba(255,255,255,.1);
  background: rgba(255,255,255,.045);
  color: #dcecd8;
  border-radius: 8px;
  height: 29px;
  padding: 0 9px;
  font-family: inherit;
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: .03em;
  cursor: pointer;
  margin-bottom: 7px;
}
.ins-target:hover { background: rgba(255,255,255,.09); }
.ins-target em { color: var(--gold); font-style: normal; text-transform: capitalize; }

.ins-upgrade {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  border: 1px solid rgba(140, 224, 107, 0.35);
  border-radius: 10px;
  background: linear-gradient(180deg, rgba(84, 154, 67, 0.55), rgba(47, 100, 38, 0.55));
  padding: 7px 9px;
  color: #f1ffe9;
  font-family: inherit;
  cursor: pointer;
  text-align: left;
  transition: filter .15s, transform .1s;
}
.ins-upgrade:hover { filter: brightness(1.12); }
.ins-upgrade:active { transform: scale(.985); }
.ins-upgrade:disabled { filter: grayscale(.8) brightness(.72); cursor: default; }
.ins-upgrade .plus {
  width: 25px; height: 25px; border-radius: 8px;
  background: rgba(255,255,255,.14);
  display: grid; place-items: center;
  font-size: 16px; font-weight: 900;
  flex: 0 0 auto;
}
.ins-upgrade .txt { flex: 1; min-width: 0; }
.ins-upgrade .txt b { display: block; font-size: 11.5px; font-weight: 900; }
.ins-upgrade .txt span { display: block; font-size: 9.5px; color: #d7ebcf; opacity: .9; margin-top: 1px; }
.ins-upgrade .cost { color: var(--gold); font-weight: 900; font-size: 12px; white-space: nowrap; }

.ins-maxed {
  text-align: center;
  padding: 8px;
  border-radius: 9px;
  border: 1px dashed rgba(255, 207, 92, 0.35);
  color: var(--gold);
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
  margin-bottom: 7px;
}

.ins-foot { display: flex; gap: 6px; margin-top: 7px; }
.ins-sell {
  flex: 1;
  height: 30px;
  border-radius: 8px;
  border: 1px solid rgba(255, 92, 104, 0.35);
  background: rgba(255, 92, 104, 0.13);
  color: #ffb9be;
  font-family: inherit;
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: .04em;
  cursor: pointer;
}
.ins-sell:hover { background: rgba(255, 92, 104, 0.22); }

/* ---------- Shop ---------- */

.shop {
  flex: 0 0 auto;
  background: linear-gradient(180deg, #203126, #17251c);
  border: 1px solid rgba(255, 246, 223, 0.11);
  border-radius: 16px;
  padding: 6px 9px 8px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.04), 0 10px 28px rgba(0,0,0,.28);
}

.shop-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 0 3px 3px;
}

.shop-title {
  font-size: 9.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--gold);
  font-weight: 900;
}

.shop-hint {
  font-size: 9.5px;
  color: var(--muted);
  font-weight: 700;
  letter-spacing: .02em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.shop-scroll {
  display: flex;
  gap: 6px;
  overflow-x: auto;
  padding: 2px 2px 4px;
  scrollbar-width: thin;
  scrollbar-color: #405a46 transparent;
  -webkit-overflow-scrolling: touch;
}

.shop-scroll::-webkit-scrollbar { height: 4px; }
.shop-scroll::-webkit-scrollbar-thumb { background: #405a46; border-radius: 4px; }

.tower-card {
  position: relative;
  flex: 1 0 96px;
  min-width: 92px;
  max-width: 128px;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px 8px 6px 6px;
  border-radius: 11px;
