// Small deterministic RNG for map decoration.
export function mulberry32(seed) {
  return function () {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Catmull-Rom spline path with arc-length lookups.

export class Track {
  constructor(waypoints, samplesPerSegment = 28) {
    this.points = [];
    const pts = waypoints;
    for (let i = 0; i < pts.length - 1; i++) {
      const p0 = pts[Math.max(0, i - 1)];
      const p1 = pts[i];
      const p2 = pts[i + 1];
      const p3 = pts[Math.min(pts.length - 1, i + 2)];
      for (let s = 0; s < samplesPerSegment; s++) {
        const t = s / samplesPerSegment;
        this.points.push(catmullRom(p0, p1, p2, p3, t));
      }
    }
    this.points.push({ ...pts[pts.length - 1] });

    this.cum = [0];
    for (let i = 1; i < this.points.length; i++) {
      const a = this.points[i - 1];
      const b = this.points[i];
      this.cum.push(this.cum[i - 1] + Math.hypot(b.x - a.x, b.y - a.y));
    }
    this.length = this.cum[this.cum.length - 1];
  }

  pointAt(d) {
    const t = Math.max(0, Math.min(this.length, d));
    let lo = 0;
    let hi = this.cum.length - 1;
    while (lo < hi - 1) {
      const mid = (lo + hi) >> 1;
      if (this.cum[mid] <= t) lo = mid;
      else hi = mid;
    }
    const a = this.points[lo];
    const b = this.points[Math.min(this.points.length - 1, lo + 1)];
    const span = this.cum[lo + 1] - this.cum[lo] || 1;
    const f = (t - this.cum[lo]) / span;
    return { x: a.x + (b.x - a.x) * f, y: a.y + (b.y - a.y) * f };
  }

  tangentAt(d) {
    const a = this.pointAt(Math.max(0, d - 3));
    const b = this.pointAt(Math.min(this.length, d + 3));
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const len = Math.hypot(dx, dy) || 1;
    return { x: dx / len, y: dy / len };
  }

  normalAt(d) {
    const t = this.tangentAt(d);
    return { x: -t.y, y: t.x };
  }

  distanceTo(x, y) {
    let best = Infinity;
    const pts = this.points;
    for (let i = 0; i < pts.length; i++) {
      const dx = pts[i].x - x;
      const dy = pts[i].y - y;
      const d2 = dx * dx + dy * dy;
      if (d2 < best) best = d2;
    }
    return Math.sqrt(best);
  }
}

function catmullRom(p0, p1, p2, p3, t) {
  const t2 = t * t;
  const t3 = t2 * t;
  return {
    x: 0.5 * ((2 * p1.x) + (-p0.x + p2.x) * t + (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * t2 + (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * t3),
    y: 0.5 * ((2 * p1.y) + (-p0.y + p2.y) * t + (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * t2 + (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * t3),
  };
}

// Small WebAudio synth — no external assets needed.

export class AudioKit {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.enabled = true;
    this.lastPop = 0;
    this.popBudget = 0;
  }

  unlock() {
    if (this.ctx) {
      if (this.ctx.state === "suspended") this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.3;
    this.master.connect(this.ctx.destination);
  }

  setEnabled(on) {
    this.enabled = on;
    if (this.master) this.master.gain.value = on ? 0.3 : 0;
  }

  get t() { return this.ctx ? this.ctx.currentTime : 0; }

  tone({ freq = 440, end = null, dur = 0.12, type = "sine", vol = 0.2, delay = 0, attack = 0.005 }) {
    if (!this.enabled || !this.ctx) return;
    const t0 = this.t + delay;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (end) osc.frequency.exponentialRampToValueAtTime(Math.max(24, end), t0 + dur);
    gain.gain.setValueAtTime(0.0001, t0);
    gain.gain.linearRampToValueAtTime(vol, t0 + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(gain).connect(this.master);
    osc.start(t0);
    osc.stop(t0 + dur + 0.02);
  }

  noise({ dur = 0.1, vol = 0.15, freq = 1800, q = 0.8, delay = 0, type = "bandpass" }) {
    if (!this.enabled || !this.ctx) return;
    const t0 = this.t + delay;
    const len = Math.max(1, Math.floor(this.ctx.sampleRate * dur));
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, t0);
    filter.frequency.exponentialRampToValueAtTime(Math.max(120, freq * 0.3), t0 + dur);
    filter.Q.value = q;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(vol, t0);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(filter).connect(gain).connect(this.master);
    src.start(t0);
  }

  pop(size = 14) {
    if (!this.enabled || !this.ctx) return;
    const now = performance.now();
    if (now - this.lastPop < 34) return;
    this.lastPop = now;
    const base = 620 + (14 - size) * 14 + Math.random() * 120;
    this.tone({ freq: base, end: base * 0.45, dur: 0.09, type: "triangle", vol: 0.11 });
    this.noise({ dur: 0.055, vol: 0.055, freq: 2400 });
  }

  shoot(kind = "dart") {
    if (!this.enabled || !this.ctx) return;
    const cfg = {
      dart: { freq: 900, end: 480, dur: 0.055, type: "square", vol: 0.035 },
      tack: { freq: 1300, end: 700, dur: 0.04, type: "square", vol: 0.025 },
      boomerang: { freq: 300, end: 520, dur: 0.12, type: "sine", vol: 0.05 },
      bomb: { freq: 110, end: 48, dur: 0.16, type: "sawtooth", vol: 0.09 },
      laser: { freq: 1500, end: 900, dur: 0.03, type: "sawtooth", vol: 0.02 },
      magic: { freq: 720, end: 1100, dur: 0.09, type: "triangle", vol: 0.04 },
      sniper: { freq: 180, end: 70, dur: 0.14, type: "square", vol: 0.06 },
    }[kind] || { freq: 700, end: 400, dur: 0.05, type: "triangle", vol: 0.03 };
    this.tone(cfg);
  }

  boom() {
    this.noise({ dur: 0.34, vol: 0.24, freq: 700, q: 0.5, type: "lowpass" });
    this.tone({ freq: 90, end: 34, dur: 0.3, type: "sine", vol: 0.22 });
  }

  ice() {
    this.tone({ freq: 1400, end: 2300, dur: 0.24, type: "sine", vol: 0.05 });
    this.tone({ freq: 2100, end: 1100, dur: 0.3, type: "triangle", vol: 0.03, delay: 0.04 });
  }

  place() {
    this.tone({ freq: 300, end: 520, dur: 0.1, type: "triangle", vol: 0.1 });
    this.tone({ freq: 600, end: 760, dur: 0.1, type: "sine", vol: 0.06, delay: 0.07 });
  }

  upgrade() {
    [523, 659, 784, 1046].forEach((f, i) => {
      this.tone({ freq: f, dur: 0.16, type: "triangle", vol: 0.07, delay: i * 0.06 });
    });
  }

  error() {
    this.tone({ freq: 180, end: 130, dur: 0.18, type: "square", vol: 0.06 });
  }

  sell() {
    this.tone({ freq: 520, end: 260, dur: 0.14, type: "triangle", vol: 0.08 });
  }

  leak() {
    this.tone({ freq: 150, end: 60, dur: 0.4, type: "sawtooth", vol: 0.14 });
    this.noise({ dur: 0.25, vol: 0.1, freq: 500, type: "lowpass" });
  }

  waveStart() {
    [392, 523, 659].forEach((f, i) => {
      this.tone({ freq: f, dur: 0.2, type: "triangle", vol: 0.07, delay: i * 0.09 });
    });
  }

  roundClear() {
    [659, 784, 1046, 1318].forEach((f, i) => {
      this.tone({ freq: f, dur: 0.24, type: "triangle", vol: 0.07, delay: i * 0.08 });
    });
  }

  win() {
    [523, 659, 784, 1046, 1318, 1568].forEach((f, i) => {
      this.tone({ freq: f, dur: 0.42, type: "triangle", vol: 0.08, delay: i * 0.12 });
    });
  }

  lose() {
    [392, 330, 262, 196].forEach((f, i) => {
      this.tone({ freq: f, dur: 0.5, type: "sawtooth", vol: 0.06, delay: i * 0.16 });
    });
  }

  moab() {
    this.tone({ freq: 70, end: 40, dur: 1.2, type: "sawtooth", vol: 0.12 });
    this.noise({ dur: 1.4, vol: 0.1, freq: 300, type: "lowpass" });
  }
}

// All rendering: baked meadow background, towers, bloons, projectiles, FX.

import { W, H, BLOONS, TOWER_BY_ID, towerStats, mulberry32 } from "./config.js";

export class Renderer {
  constructor(canvas, track, pathWidth) {
    this.canvas = canvas;
    this.ctx = canvas.getContext("2d");
    this.track = track;
    this.pathWidth = pathWidth;
    this.dpr = 1;
    this.balloonGrads = new Map();
    this.decor = [];
    this.blockers = [];
    this.pond = { x: 104, y: 646, rx: 112, ry: 58 };
    this.makeDecor();
    this.buildBackground();
    this.resize();
  }

  resize() {
    const dpr = Math.min(2.5, window.devicePixelRatio || 1);
    const rect = this.canvas.getBoundingClientRect();
    const w = Math.max(320, Math.round(rect.width * dpr));
    const h = Math.max(180, Math.round(rect.height * dpr));
    if (this.canvas.width !== w || this.canvas.height !== h) {
      this.canvas.width = w;
      this.canvas.height = h;
    }
    this.dpr = dpr;
  }

  makeDecor() {
    const rng = mulberry32(90210);
    const t = this.track;
    const tooCloseToPond = (x, y) => {
      const dx = (x - this.pond.x) / (this.pond.rx + 26);
      const dy = (y - this.pond.y) / (this.pond.ry + 26);
      return dx * dx + dy * dy < 1;
    };
    const free = (x, y, margin, scale = 1) => {
      if (x < 30 * scale || x > W - 30 * scale || y < 40 || y > H - 20) return false;
      if (t.distanceTo(x, y) < margin) return false;
      if (tooCloseToPond(x, y)) return false;
      for (const d of this.decor) {
        if (Math.hypot(d.x - x, d.y - y) < (d.r + 24) * scale) return false;
      }
      return true;
    };

    const tryPlace = (kind, count, margin, rMin, rMax, blocking) => {
      let placed = 0;
      let guard = 0;
      while (placed < count && guard++ < 900) {
        const x = 40 + rng() * (W - 80);
        const y = 70 + rng() * (H - 100);
        const r = rMin + rng() * (rMax - rMin);
        if (!free(x, y, margin + r)) continue;
        const d = { kind, x, y, r, blocking, seed: rng(), lean: (rng() - 0.5) * 0.3 };
        this.decor.push(d);
        if (blocking) this.blockers.push(d);
        placed++;
      }
    };

    tryPlace("tree", 15, this.pathWidth / 2 + 6, 25, 38, true);
    tryPlace("bush", 26, 43, 13, 20, true);
    tryPlace("rock", 9, 40, 8, 13, true);

    for (let i = 0; i < 85; i++) {
      const x = 20 + rng() * (W - 40);
      const y = 60 + rng() * (H - 80);
      if (t.distanceTo(x, y) < 35 + rng() * 8) continue;
      if (tooCloseToPond(x, y)) continue;
      const kind = rng() < 0.55 ? "tuft" : rng() < 0.62 ? "flower" : "pebble";
      this.decor.push({ kind, x, y, r: 3 + rng() * 5, blocking: false, seed: rng(), hue: rng() });
    }

    // A few hand-placed clumps framing the start and exit.
    for (const [x, y, r] of [[58, 46, 22], [1100, 48, 19], [1230, 560, 17], [390, 662, 19], [780, 674, 17], [57, 300, 20]]) {
      if (t.distanceTo(x, y) > 48) {
        const d = { kind: "tree", x, y, r, blocking: true, seed: 0.4, lean: 0.1 };
        this.decor.push(d);
        this.blockers.push(d);
      }
    }
    this.decor.sort((a, b) => a.y - b.y);
    this.blockers = this.decor.filter((d) => d.blocking);
  }

  buildBackground() {
    const bg = document.createElement("canvas");
    bg.width = W * 2;
    bg.height = H * 2;
    const c = bg.getContext("2d");
    c.scale(2, 2);
    const rng = mulberry32(424242);

    // Base grass.
    const grad = c.createLinearGradient(0, 0, W * 0.3, H);
    grad.addColorStop(0, "#8ccb5d");
    grad.addColorStop(0.45, "#79bd4e");
    grad.addColorStop(1, "#63a83f");
    c.fillStyle = grad;
    c.fillRect(0, 0, W, H);

    // Mown bands.
    for (let i = 0; i < 17; i++) {
      c.fillStyle = i % 2 ? "rgba(255,255,220,0.035)" : "rgba(20,70,20,0.045)";
      c.beginPath();
      c.moveTo(0, i * 44);
      c.lineTo(W, i * 44 - 70);
      c.lineTo(W, i * 44 - 20);
      c.lineTo(0, i * 44 + 50);
      c.closePath();
      c.fill();
    }

    // Fine grass texture.
    for (let i = 0; i < 5200; i++) {
      const x = rng() * W;
      const y = rng() * H;
      const a = 0.04 + rng() * 0.08;
      c.strokeStyle = rng() < 0.5 ? `rgba(30,80,20,${a})` : `rgba(220,255,190,${a})`;
      c.lineWidth = 0.8;
      c.beginPath();
      c.moveTo(x, y);
      c.lineTo(x + (rng() - 0.5) * 3, y - 2 - rng() * 4);
      c.stroke();
    }

    this.drawPond(c, rng);
    this.drawPath(c, rng);
    this.drawStartGate(c);
    this.drawExitGate(c);

    // Decorative ground items go under the big trees.
    for (const d of this.decor) {
      if (d.kind === "tuft" || d.kind === "flower" || d.kind === "pebble") this.drawGroundItem(c, d, rng);
    }
    // Flat shadows for trees/bushes then bodies.
    for (const d of this.decor) {
      if (d.kind === "tree" || d.kind === "bush" || d.kind === "rock") this.drawDecorShadow(c, d);
    }
    for (const d of this.decor) {
      if (d.kind === "tree") this.drawTree(c, d, rng);
      else if (d.kind === "bush") this.drawBush(c, d, rng);
      else if (d.kind === "rock") this.drawRock(c, d);
    }

    // Soft corner shading.
    const vign = c.createRadialGradient(W * 0.5, H * 0.48, H * 0.28, W * 0.5, H * 0.5, H * 0.92);
    vign.addColorStop(0, "rgba(15,40,12,0)");
    vign.addColorStop(0.75, "rgba(15,40,12,0.06)");
    vign.addColorStop(1, "rgba(10,28,8,0.22)");
    c.fillStyle = vign;
    c.fillRect(0, 0, W, H);

    this.bg = bg;
  }

  drawPond(c, rng) {
    const { x, y, rx, ry } = this.pond;
    const g = c.createRadialGradient(x - rx * 0.2, y - ry * 0.3, 4, x, y, rx);
    g.addColorStop(0, "#63c7d6");
    g.addColorStop(0.55, "#3d99b5");
    g.addColorStop(1, "#2a7895");
    c.save();
    c.beginPath();
    c.ellipse(x, y, rx + 9, ry + 9, 0, 0, Math.PI * 2);
    c.fillStyle = "rgba(48,83,30,0.45)";
    c.fill();
    c.beginPath();
    c.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
    c.fillStyle = g;
    c.fill();
    c.clip();
    c.strokeStyle = "rgba(220,248,255,0.3)";
    c.lineWidth = 2;
    for (let i = 0; i < 4; i++) {
      c.beginPath();
      c.ellipse(x - 20 + i * 18, y - 8 + i * 6, 30 + i * 4, 8, -0.2, 0.2, Math.PI * 0.9);
      c.stroke();
    }
    c.restore();

    c.strokeStyle = "rgba(50,84,32,0.75)";
    c.lineWidth = 3;
    c.beginPath();
    c.ellipse(x, y, rx + 1, ry + 1, 0, 0, Math.PI * 2);
    c.stroke();

    // Lily pads.
    for (const [lx, ly, lr, rot] of [[-42, 14, 17, 0.4], [28, 22, 13, 2.1], [-5, -18, 11, 4.2], [56, -6, 14, 1.2], [-62, -20, 10, 3.4]]) {
      c.beginPath();
      c.ellipse(lx * 0.6 + x, ly * 0.55 + y, lr, lr * 0.72, rot, 0.2, Math.PI * 2 - 0.1);
      c.lineTo(lx * 0.6 + x, ly * 0.55 + y);
      c.closePath();
      c.fillStyle = "#5aa84a";
      c.fill();
      c.strokeStyle = "rgba(30,80,35,.5)";
      c.lineWidth = 1;
      c.stroke();
    }
    // Reeds at edges.
    for (let i = 0; i < 9; i++) {
      const ang = Math.PI * (0.15 + rng() * 0.7) + Math.PI;
      const bx = x + Math.cos(ang) * (rx - 4);
      const by = y + Math.sin(ang) * (ry - 2);
      c.strokeStyle = "#4c8a39";
      c.lineWidth = 2;
      c.beginPath();
      c.moveTo(bx, by);
      c.quadraticCurveTo(bx + 4, by - 16, bx + 1 + rng() * 5, by - 30);
      c.stroke();
      c.fillStyle = "#7d5234";
      c.beginPath();
      c.ellipse(bx + 2, by - 30, 2.5, 6, 0.1, 0, Math.PI * 2);
      c.fill();
    }
  }

  drawPath(c, rng) {
    const path = new Path2D();
    const pts = this.track.points;
    path.moveTo(pts[0].x, pts[0].y);
    for (let i = 1; i < pts.length; i++) path.lineTo(pts[i].x, pts[i].y);

    c.lineCap = "round";
    c.lineJoin = "round";
    c.strokeStyle = "rgba(40,60,24,0.28)";
    c.lineWidth = 80;
    c.save();
    c.translate(0, 5);
    c.stroke(path);
    c.restore();

    c.strokeStyle = "#4a331d";
    c.lineWidth = 76;
    c.stroke(path);

    c.strokeStyle = "#9d7544";
    c.lineWidth = 67;
    c.stroke(path);

    c.strokeStyle = "#c49a5f";
    c.lineWidth = 56;
    c.stroke(path);

    c.strokeStyle = "rgba(224,190,137,0.55)";
    c.lineWidth = 30;
    c.stroke(path);

    // Worn tyre-track style lines.
    c.strokeStyle = "rgba(120,86,48,0.24)";
    c.lineWidth = 3;
    c.setLineDash([16, 22]);
    c.stroke(path);
    c.setLineDash([]);

    // Edge stones.
    for (let d = 14; d < this.track.length - 6; d += 26) {
      const p = this.track.pointAt(d);
      const n = this.track.normalAt(d);
      for (const side of [-1, 1]) {
        const off = 35 + rng() * 3;
        const sx = p.x + n.x * off * side;
        const sy = p.y + n.y * off * side;
        const r = 3.5 + rng() * 3.5;
        c.fillStyle = rng() < 0.5 ? "#8a6639" : "#a47c48";
        c.beginPath();
        c.ellipse(sx, sy, r, r * 0.72, rng() * 3, 0, Math.PI * 2);
        c.fill();
        c.fillStyle = "rgba(255,235,190,0.22)";
        c.beginPath();
        c.ellipse(sx - 0.8, sy - 1, r * 0.55, r * 0.36, 0, 0, Math.PI * 2);
        c.fill();
      }
    }

    // Pebbles in the track.
    for (let d = 10; d < this.track.length; d += 17) {
      const p = this.track.pointAt(d);
      const n = this.track.normalAt(d);
      const off = (rng() - 0.5) * 46;
      c.fillStyle = `rgba(110,78,42,${0.1 + rng() * 0.16})`;
      c.beginPath();
      c.ellipse(p.x + n.x * off, p.y + n.y * off, 1 + rng() * 2.6, 1 + rng() * 1.6, rng() * 3, 0, Math.PI * 2);
      c.fill();
    }
  }

  drawStartGate(c) {
    const p = this.track.pointAt(6);
    c.save();
    c.translate(p.x - 8, p.y);
    // Cave mouth.
    const hole = c.createRadialGradient(-10, 0, 4, 0, 0, 54);
    hole.addColorStop(0, "#141b0d");
    hole.addColorStop(0.7, "#1f2a14");
    hole.addColorStop(1, "#33401f");
    c.fillStyle = hole;
    c.beginPath();
    c.ellipse(-6, 2, 40, 52, 0, 0, Math.PI * 2);
    c.fill();
    // Rocks around it.
    const rocks = [[-34, -38, 20], [-12, -50, 18], [14, -44, 16], [28, -20, 13], [30, 16, 15], [18, 42, 17], [-8, 50, 16], [-32, 38, 18], [-42, 8, 15]];
    for (const [x, y, r] of rocks) {
      c.fillStyle = "#6c6a5c";
      c.beginPath();
      c.ellipse(x, y, r, r * 0.8, (x + y) * 0.02, 0, Math.PI * 2);
      c.fill();
      c.strokeStyle = "rgba(40,44,34,.55)";
      c.lineWidth = 2;
      c.stroke();
      c.fillStyle = "rgba(200,200,170,.24)";
      c.beginPath();
      c.ellipse(x - r * 0.25, y - r * 0.3, r * 0.45, r * 0.28, 0, 0, Math.PI * 2);
      c.fill();
    }
    // Vines.
    c.strokeStyle = "#3f7a34";
    c.lineWidth = 3;
    for (const [vx, vy, len] of [[-30, -44, 26], [-2, -52, 34], [22, -40, 20]]) {
      c.beginPath();
      c.moveTo(vx, vy);
      c.quadraticCurveTo(vx + 5, vy + len * 0.6, vx - 2, vy + len);
      c.stroke();
      c.fillStyle = "#5ea148";
      for (let i = 0; i < 3; i++) {
        c.beginPath();
        c.ellipse(vx + 2 + i * 3, vy + (len * (i + 1)) / 3.5, 3, 5, 0.6, 0, Math.PI * 2);
        c.fill();
      }
    }
    c.restore();
  }

  drawExitGate(c) {
    const p = this.track.pointAt(this.track.length - 18);
    c.save();
    c.translate(p.x - 6, p.y);
    // Stone wall.
    c.fillStyle = "#7e7a6b";
    c.beginPath();
    c.roundRect(-34, -38, 76, 78, 8);
    c.fill();
    c.strokeStyle = "rgba(40,40,30,.55)";
    c.lineWidth = 3;
    c.stroke();
    const blocks = [[-24, -28, 20, 14], [4, -30, 22, 15], [-24, -6, 18, 13], [2, -8, 20, 13], [-20, 16, 20, 13], [6, 16, 18, 13]];
    for (const [x, y, w, h] of blocks) {
      c.fillStyle = "#98927e";
      c.beginPath();
      c.roundRect(x, y, w, h, 3);
      c.fill();
      c.strokeStyle = "rgba(60,58,46,.35)";
      c.lineWidth = 1.5;
      c.stroke();
    }
    // Dark gate.
    c.fillStyle = "#20261d";
    c.beginPath();
    c.roundRect(-12, -2, 32, 42, [15, 15, 2, 2]);
    c.fill();
    c.strokeStyle = "#5f5a49";
    c.lineWidth = 3;
    c.stroke();
    // Red flag.
    c.strokeStyle = "#4c3f2a";
    c.lineWidth = 2.5;
    c.beginPath();
    c.moveTo(22, -38);
    c.lineTo(22, -72);
    c.stroke();
    c.fillStyle = "#e14b4b";
    c.beginPath();
    c.moveTo(23, -70);
    c.lineTo(46, -62);
    c.lineTo(23, -52);
    c.closePath();
    c.fill();
    c.fillStyle = "rgba(0,0,0,.2)";
    c.beginPath();
    c.moveTo(23, -70);
    c.lineTo(35, -66);
    c.lineTo(23, -52);
    c.closePath();
    c.fill();
    c.restore();
  }

  drawGroundItem(c, d, rng) {
    const { x, y } = d;
    if (d.kind === "tuft") {
      c.strokeStyle = "rgba(42,105,34,.65)";
      c.lineWidth = 1.4;
      for (let i = 0; i < 3; i++) {
        c.beginPath();
        c.moveTo(x, y);
        c.quadraticCurveTo(x + (i - 1) * 4, y - 5, x + (i - 1) * 7, y - 3 - d.r);
        c.stroke();
      }
    } else if (d.kind === "flower") {
      const colors = ["#fff6b8", "#ffd0e8", "#c9b3ff", "#ffffff"];
      const col = colors[Math.floor(d.hue * colors.length) % colors.length];
      c.strokeStyle = "rgba(40,100,30,.6)";
      c.lineWidth = 1.2;
      c.beginPath();
      c.moveTo(x, y);
      c.lineTo(x, y - 8);
      c.stroke();
      for (let i = 0; i < 5; i++) {
        const a = (i / 5) * Math.PI * 2;
        c.fillStyle = col;
        c.beginPath();
        c.ellipse(x + Math.cos(a) * 2.6, y - 8 + Math.sin(a) * 2.6, 2, 1.7, a, 0, Math.PI * 2);
        c.fill();
      }
      c.fillStyle = "#f0b83e";
      c.beginPath();
      c.arc(x, y - 8, 1.6, 0, Math.PI * 2);
      c.fill();
    } else {
      c.fillStyle = "rgba(120,95,60,.5)";
      c.beginPath();
      c.ellipse(x, y, d.r, d.r * 0.6, 0, 0, Math.PI * 2);
      c.fill();
    }
  }

  drawDecorShadow(c, d) {
    c.fillStyle = "rgba(24,60,20,0.26)";
    c.beginPath();
    c.ellipse(d.x + 6, d.y + 4, d.r * 1.05, d.r * 0.52, d.lean, 0, Math.PI * 2);
    c.fill();
  }

  drawTree(c, d, rng) {
    const { x, y, r } = d;
    const s = r / 30;
    // Trunk.
    c.fillStyle = "#6d4a2a";
    c.beginPath();
    c.roundRect(x - 4 * s, y - 8 * s, 8 * s, 20 * s, 3 * s);
    c.fill();
    c.strokeStyle = "rgba(50,30,12,.35)";
    c.lineWidth = 1.2;
    c.stroke();
    // Canopy clumps.
    const clumps = [[0, -32, 22], [-16, -18, 16], [17, -18, 15], [0, -12, 17]];
    for (const [cx, cy, cr] of clumps) {
      const g = c.createRadialGradient(x + cx * s - cr * s * 0.3, y + cy * s - cr * s * 0.35, 2, x + cx * s, y + cy * s, cr * s * 1.3);
      g.addColorStop(0, "#74b84a");
      g.addColorStop(0.6, "#4e9636");
      g.addColorStop(1, "#2f6f27");
      c.fillStyle = g;
      c.beginPath();
      c.arc(x + cx * s, y + cy * s, cr * s, 0, Math.PI * 2);
      c.fill();
    }
    // Leaf speckles.
    for (let i = 0; i < 7; i++) {
      const a = rng() * Math.PI * 2;
      const rr = rng() * 20 * s;
      c.fillStyle = "rgba(180,240,140,.3)";
      c.beginPath();
      c.arc(x + Math.cos(a) * rr, y - 24 * s + Math.sin(a) * rr, 1.6, 0, Math.PI * 2);
      c.fill();
    }
  }

  drawBush(c, d, rng) {
    const { x, y, r } = d;
    const s = r / 16;
    const g = c.createRadialGradient(x - r * 0.3, y - r * 0.5, 2, x, y, r * 1.4);
    g.addColorStop(0, "#7cc252");
    g.addColorStop(0.7, "#4e9838");
    g.addColorStop(1, "#347229");
    c.fillStyle = g;
    for (const [ox, oy, rr] of [[-9, 0, 10], [8, 0, 10], [0, -7, 12]]) {
      c.beginPath();
      c.arc(x + ox * s, y + oy * s, rr * s, 0, Math.PI * 2);
      c.fill();
    }
    for (let i = 0; i < 4; i++) {
      c.fillStyle = "rgba(200,250,160,.3)";
      c.beginPath();
      c.arc(x - 8 + rng() * 16, y - 8 + rng() * 8, 1.2, 0, Math.PI * 2);
      c.fill();
    }
    if (rng() < 0.6) {
      c.fillStyle = "#ff7ea8";
      c.beginPath();
      c.arc(x + 5, y - 8, 2.2, 0, Math.PI * 2);
      c.fill();
    }
  }

  drawRock(c, d) {
    const { x, y, r } = d;
    c.fillStyle = "#827c6b";
    c.beginPath();
    c.moveTo(x - r, y + r * 0.35);
    c.lineTo(x - r * 0.55, y - r * 0.8);
    c.lineTo(x + r * 0.3, y - r);
    c.lineTo(x + r, y - r * 0.2);
    c.lineTo(x + r * 0.6, y + r * 0.6);
    c.lineTo(x - r * 0.4, y + r * 0.7);
    c.closePath();
    c.fill();
    c.strokeStyle = "rgba(50,50,40,.4)";
    c.lineWidth = 1.4;
    c.stroke();
    c.fillStyle = "rgba(220,220,200,.28)";
    c.beginPath();
    c.ellipse(x - r * 0.25, y - r * 0.4, r * 0.4, r * 0.22, -0.4, 0, Math.PI * 2);
    c.fill();
    c.fillStyle = "rgba(90,120,60,.55)";
    c.beginPath();
    c.ellipse(x + r * 0.4, y + r * 0.45, r * 0.25, r * 0.1, 0.2, 0, Math.PI * 2);
    c.fill();
  }

  // ---------------------------------------------------------------- frame

  draw(game, time) {
    const ctx = this.ctx;
    this.resize();
    const cw = this.canvas.width;
    const ch = this.canvas.height;
    const shake = game.shake || 0;

    ctx.setTransform(cw / W, 0, 0, ch / H, 0, 0);
    ctx.clearRect(0, 0, W, H);
    if (shake > 0.1) {
      ctx.translate((Math.random() - 0.5) * shake, (Math.random() - 0.5) * shake);
    }

    ctx.drawImage(this.bg, 0, 0, W, H);

    // Range/placement indicators under entities.
    if (game.placing && game.pointer) {
      const def = TOWER_BY_ID[game.placing];
      if (def) this.drawRange(ctx, game.pointer.x, game.pointer.y, towerStats(def, 0).range, game.placementValid ? "#8ce06b" : "#ff5c68", 0.13);
    }
    if (game.selected) {
      this.drawRange(ctx, game.selected.x, game.selected.y, game.selected.stats.range, "#ffcf5c", 0.1);
    }

    for (const b of game.balloons) this.drawBalloon(ctx, b, time);
    for (const t of game.towers) this.drawTower(ctx, t, time);

    for (const p of game.projectiles) this.drawProjectile(ctx, p, time);
    this.drawEffects(ctx, game, time);

    for (const p of game.particles) this.drawParticle(ctx, p);
    for (const t of game.texts) this.drawText(ctx, t);

    if (game.selected) this.drawSelection(ctx, game.selected, time);
    if (game.placing && game.pointer) this.drawGhost(ctx, game, time);

    // Screen flash on life loss.
    if (game.damageFlash > 0) {
      ctx.fillStyle = `rgba(255, 40, 55, ${Math.min(0.4, game.damageFlash * 0.4)})`;
      ctx.fillRect(0, 0, W, H);
    }
  }

  drawRange(ctx, x, y, range, color, alpha) {
    if (range > 3000) return;
    ctx.save();
    ctx.beginPath();
    ctx.arc(x, y, range, 0, Math.PI * 2);
    ctx.fillStyle = hexA(color, alpha);
    ctx.fill();
    ctx.setLineDash([7, 7]);
    ctx.lineWidth = 2;
    ctx.strokeStyle = hexA(color, 0.72);
    ctx.stroke();
    ctx.restore();
  }

  drawSelection(ctx, t, time) {
    ctx.save();
    ctx.translate(t.x, t.y);
    ctx.rotate(time * 0.8);
    ctx.setLineDash([5, 8]);
    ctx.lineWidth = 2;
    ctx.strokeStyle = "rgba(255, 207, 92, 0.75)";
    ctx.beginPath();
    ctx.arc(0, 0, 31, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
  }

  drawGhost(ctx, game, time) {
    const def = TOWER_BY_ID[game.placing];
    if (!def) return;
    const p = game.pointer;
    ctx.save();
    ctx.globalAlpha = 0.62;
    this.drawTowerBody(ctx, def.id, 0, -Math.PI / 2, time, p.x, p.y, 1);
    ctx.restore();
    // Footprint.
    ctx.save();
    ctx.beginPath();
    ctx.arc(p.x, p.y, 26, 0, Math.PI * 2);
    ctx.strokeStyle = game.placementValid ? "rgba(190,255,160,.9)" : "rgba(255,110,120,.9)";
    ctx.lineWidth = 2.5;
    ctx.setLineDash([6, 6]);
    ctx.stroke();
    ctx.restore();
  }

  // ---------------------------------------------------------------- bloons

  drawBalloon(ctx, b, time) {
    const def = BLOONS[b.type];
    const r = b.radius;
    if (b.type === "moab") {
      this.drawMoab(ctx, b, time);
      return;
    }
    const bob = Math.sin(time * 3.1 + b.phase) * 1.6;
    const sway = Math.sin(time * 2.2 + b.phase) * 0.055;

    ctx.save();
    // Ground shadow.
    ctx.fillStyle = "rgba(28,60,22,0.16)";
    ctx.beginPath();
    ctx.ellipse(b.x + 3, b.y + 7, r * 0.85, r * 0.4, 0, 0, Math.PI * 2);
    ctx.fill();

    // String.
    ctx.strokeStyle = "rgba(60,55,40,0.45)";
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(b.x + Math.sin(sway) * r * 0.3, b.y + r * 0.98);
    ctx.quadraticCurveTo(b.x + Math.sin(time * 2 + b.phase) * 5, b.y + r * 1.5, b.x + Math.sin(time * 1.5 + b.phase) * 7, b.y + r * 2.15);
    ctx.stroke();

    ctx.translate(b.x, b.y + bob);
    ctx.rotate(sway);

    // Knot.
    ctx.fillStyle = def.shade;
    ctx.beginPath();
    ctx.moveTo(-3.6, r * 0.88);
    ctx.lineTo(3.6, r * 0.88);
    ctx.lineTo(0, r * 1.14);
    ctx.closePath();
    ctx.fill();

    // Body.
    const grad = this.balloonGradient(ctx, b.type, r);
    ctx.beginPath();
    ctx.ellipse(0, 0, r * 0.9, r * 1.1, 0, 0, Math.PI * 2);
    ctx.fillStyle = grad;
    ctx.fill();

    if (def.pattern === "zebra") {
      ctx.save();
      ctx.beginPath();
      ctx.ellipse(0, 0, r * 0.9, r * 1.1, 0, 0, Math.PI * 2);
      ctx.clip();
      ctx.fillStyle = "#20242b";
      for (let i = -3; i <= 3; i++) {
        ctx.save();
        ctx.translate(i * 6.5, 0);
        ctx.rotate(0.5);
        ctx.fillRect(-2, -r * 1.4, 3.2, r * 2.8);
        ctx.restore();
      }
      ctx.restore();
    } else if (def.pattern === "rainbow") {
      ctx.save();
      ctx.beginPath();
      ctx.ellipse(0, 0, r * 0.9, r * 1.1, 0, 0, Math.PI * 2);
      ctx.clip();
      const rg = ctx.createLinearGradient(-r, -r, r, r);
      rg.addColorStop(0, "#ff5d68");
      rg.addColorStop(0.22, "#ffb84d");
      rg.addColorStop(0.44, "#ffe94d");
      rg.addColorStop(0.62, "#69e06a");
      rg.addColorStop(0.8, "#5bb8ff");
      rg.addColorStop(1, "#c07bff");
      ctx.fillStyle = rg;
      ctx.fillRect(-r, -r, r * 2, r * 2);
      ctx.restore();
    } else if (def.pattern === "ceramic") {
      ctx.save();
      ctx.beginPath();
      ctx.ellipse(0, 0, r * 0.9, r * 1.1, 0, 0, Math.PI * 2);
      ctx.clip();
      ctx.strokeStyle = "rgba(90,52,22,.5)";
      ctx.lineWidth = 1.3;
      ctx.beginPath();
      ctx.moveTo(-r * 0.6, -r * 0.6);
      ctx.lineTo(-r * 0.2, -r * 0.2);
      ctx.lineTo(-r * 0.5, r * 0.15);
      ctx.moveTo(r * 0.55, -r * 0.7);
      ctx.lineTo(r * 0.2, -r * 0.3);
      ctx.lineTo(r * 0.55, r * 0.05);
      ctx.moveTo(-r * 0.1, r * 0.5);
      ctx.lineTo(r * 0.25, r * 0.65);
      ctx.stroke();
      ctx.restore();
    }

    // Highlight.
    const hl = ctx.createRadialGradient(-r * 0.34, -r * 0.5, 0.5, -r * 0.34, -r * 0.5, r * 0.62);
    hl.addColorStop(0, "rgba(255,255,255,0.85)");
    hl.addColorStop(0.5, "rgba(255,255,255,0.22)");
    hl.addColorStop(1, "rgba(255,255,255,0)");
    ctx.fillStyle = hl;
    ctx.beginPath();
    ctx.ellipse(-r * 0.3, -r * 0.42, r * 0.4, r * 0.5, -0.5, 0, Math.PI * 2);
    ctx.fill();

    // Rim shade.
    ctx.strokeStyle = hexA(def.shade, 0.5);
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.ellipse(0, 0, r * 0.9, r * 1.1, 0, 0, Math.PI * 2);
    ctx.stroke();

    // Damage flash.
    if (b.hitFlash > 0) {
      ctx.globalAlpha = Math.min(0.85, b.hitFlash * 3);
      ctx.fillStyle = "#ffffff";
      ctx.beginPath();
      ctx.ellipse(0, 0, r * 0.9, r * 1.1, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
    }

    // Frozen tint.
    if (b.slowTimer > 0) {
      ctx.fillStyle = "rgba(160,235,255,0.25)";
      ctx.beginPath();
      ctx.ellipse(0, 0, r * 0.9, r * 1.1, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = "rgba(220,250,255,0.7)";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(-r * 0.5, -r * 0.2);
      ctx.lineTo(-r * 0.25, 0);
      ctx.lineTo(-r * 0.5, r * 0.3);
      ctx.stroke();
    }

    ctx.restore();

    if (b.maxHp > 1) this.drawHpBar(ctx, b.x, b.y - r * 1.35, r * 2.1, b.hp / b.maxHp);
  }

  drawMoab(ctx, b, time) {
    const r = b.radius;
    const angle = b.heading || 0;
    ctx.save();
    ctx.fillStyle = "rgba(28,60,22,0.2)";
    ctx.beginPath();
    ctx.ellipse(b.x + 5, b.y + 24, 55, 14, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.translate(b.x, b.y);
    ctx.rotate(angle);
    const g = ctx.createLinearGradient(0, -r, 0, r);
    g.addColorStop(0, "#d5dde8");
    g.addColorStop(0.35, "#a7b2c0");
    g.addColorStop(0.75, "#77818f");
    g.addColorStop(1, "#4f5968");
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(0, 0, r * 1.6, r * 0.86, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = "rgba(45,52,64,.6)";
    ctx.lineWidth = 2;
    ctx.stroke();

    // Nose cap.
    ctx.fillStyle = "#b7c2d0";
    ctx.beginPath();
    ctx.ellipse(r * 1.14, 0, r * 0.5, r * 0.66, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = "rgba(255,255,255,.35)";
    ctx.stroke();

    // Fins.
    ctx.fillStyle = "#5b6675";
    for (const s of [-1, 1]) {
      ctx.beginPath();
      ctx.moveTo(-r * 1.3, 0);
      ctx.lineTo(-r * 1.7, s * r * 0.8);
      ctx.lineTo(-r * 1.05, s * r * 0.45);
      ctx.closePath();
      ctx.fill();
    }

    // Stripes.
    ctx.save();
    ctx.beginPath();
    ctx.ellipse(0, 0, r * 1.58, r * 0.84, 0, 0, Math.PI * 2);
    ctx.clip();
    ctx.fillStyle = "rgba(214,64,68,.85)";
    ctx.fillRect(-r * 0.45, -r, r * 0.22, r * 2);
    ctx.fillRect(r * 0.05, -r, r * 0.12, r * 2);
    ctx.fillStyle = "rgba(255,255,255,.12)";
    ctx.fillRect(-r * 1.6, -r * 0.72, r * 3.2, r * 0.22);
    ctx.restore();

    // Rivets.
    ctx.fillStyle = "rgba(50,58,70,.6)";
    for (let i = -5; i <= 5; i++) {
      ctx.beginPath();
      ctx.arc(i * 8.5, r * 0.5, 1.4, 0, Math.PI * 2);
      ctx.fill();
    }

    // Eyes.
    ctx.fillStyle = "#242b35";
    ctx.beginPath();
    ctx.ellipse(r * 0.68, -r * 0.18, 7.5, 5, 0, 0, Math.PI * 2);
    ctx.fill();
    const eyeGlow = 0.55 + Math.sin(time * 4) * 0.25;
    ctx.fillStyle = `rgba(255,90,80,${eyeGlow})`;
    ctx.beginPath();
    ctx.arc(r * 0.7, -r * 0.18, 3, 0, Math.PI * 2);
    ctx.fill();

    // Propeller.
    ctx.strokeStyle = "rgba(80,90,104,.8)";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(-r * 1.55, 0);
    ctx.lineTo(-r * 1.8, 0);
    ctx.stroke();
    ctx.save();
    ctx.translate(-r * 1.82, 0);
    ctx.rotate(time * 14);
    ctx.fillStyle = "rgba(220,228,238,.6)";
    ctx.fillRect(-1.6, -10, 3.2, 20);
    ctx.restore();

    if (b.hitFlash > 0) {
      ctx.globalAlpha = Math.min(0.6, b.hitFlash * 2.5);
      ctx.fillStyle = "#fff";
      ctx.beginPath();
      ctx.ellipse(0, 0, r * 1.6, r * 0.86, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
    }
    ctx.restore();

    this.drawHpBar(ctx, b.x, b.y - 42, 78, b.hp / b.maxHp, "#ff6c6c");
    // Label.
    ctx.fillStyle = "rgba(255,246,223,.85)";
    ctx.font = "800 9px 'Trebuchet MS', sans-serif";
    ctx.textAlign = "center";
    ctx.fillText("MOAB", b.x, b.y - 48);
  }

  drawHpBar(ctx, x, y, w, frac, color = "#7be36b") {
    const h = 4;
    ctx.fillStyle = "rgba(20,28,20,.65)";
    ctx.beginPath();
    ctx.roundRect(x - w / 2, y, w, h, 2);
    ctx.fill();
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.roundRect(x - w / 2, y, Math.max(1, w * Math.max(0, frac)), h, 2);
    ctx.fill();
  }

  balloonGradient(ctx, type, r) {
    const key = type + ":" + Math.round(r);
    if (this.balloonGrads.has(key)) return this.balloonGrads.get(key);
    const def = BLOONS[type];
    const g = ctx.createRadialGradient(-r * 0.35, -r * 0.48, r * 0.08, 0, 0, r * 1.15);
    if (def.pattern === "rainbow") {
      g.addColorStop(0, "#fff1c9");
      g.addColorStop(1, "#ff7ab8");
    } else if (def.pattern === "white") {
      g.addColorStop(0, "#ffffff");
      g.addColorStop(0.6, "#eef3fb");
      g.addColorStop(1, "#b9c7dd");
    } else if (def.pattern === "black") {
      g.addColorStop(0, "#7a8798");
      g.addColorStop(0.5, "#3b4553");
      g.addColorStop(1, "#161b23");
    } else {
      g.addColorStop(0, def.accent);
      g.addColorStop(0.42, def.color);
      g.addColorStop(1, def.shade);
    }
    this.balloonGrads.set(key, g);
    return g;
  }

  // ---------------------------------------------------------------- towers

  drawTower(ctx, t, time) {
    ctx.save();
    ctx.fillStyle = "rgba(20,48,16,0.24)";
    ctx.beginPath();
    ctx.ellipse(t.x + 4, t.y + 9, 28, 12, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
    this.drawTowerBody(ctx, t.def.id, t.level, t.angle, time, t.x, t.y, 1, t.flash > 0);
  }

  drawTowerBody(ctx, id, level, angle, time, x, y, scale, flash = false) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(scale, scale);

    // Platform.
    const base = ctx.createRadialGradient(-6, -8, 3, 0, 0, 27);
    base.addColorStop(0, "#9a7549");
    base.addColorStop(0.7, "#715030");
    base.addColorStop(1, "#48311c");
    ctx.fillStyle = base;
    ctx.beginPath();
    ctx.arc(0, 0, 24, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = "#3a2715";
    ctx.lineWidth = 2.5;
    ctx.stroke();

    ctx.strokeStyle = "rgba(255,232,184,.3)";
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(0, 0, 19.5, 0, Math.PI * 2);
    ctx.stroke();

    // Plank grain.
    ctx.strokeStyle = "rgba(50,30,12,.24)";
    ctx.lineWidth = 1;
    for (let i = -1; i <= 1; i++) {
      ctx.beginPath();
      ctx.arc(0, 0, 12 + i * 4, 0.35, Math.PI - 0.35);
      ctx.stroke();
    }

    // Bolts.
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * Math.PI * 2 + Math.PI / 6;
      ctx.fillStyle = "#c9a96a";
      ctx.beginPath();
      ctx.arc(Math.cos(a) * 21, Math.sin(a) * 21, 1.8, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = "rgba(60,40,18,.55)";
      ctx.beginPath();
      ctx.arc(Math.cos(a) * 21 + 0.5, Math.sin(a) * 21 + 0.5, 0.8, 0, Math.PI * 2);
      ctx.fill();
    }

    // Level pips.
    for (let i = 0; i < level; i++) {
      ctx.fillStyle = "#ffcf5c";
      ctx.strokeStyle = "rgba(80,55,10,.6)";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(-8 + i * 8, 20, 2.2, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    }

    switch (id) {
      case "dart": this.artDart(ctx, angle, flash); break;
      case "tack": this.artTack(ctx, time, flash, level); break;
      case "boomerang": this.artBoomerang(ctx, angle, time, flash); break;
      case "bomb": this.artBomb(ctx, angle, flash); break;
      case "ice": this.artIce(ctx, time, level); break;
      case "sniper": this.artSniper(ctx, angle, flash); break;
      case "ninja": this.artNinja(ctx, angle, time, level); break;
      case "wizard": this.artWizard(ctx, angle, time, level); break;
      case "super": this.artSuper(ctx, angle, time, level); break;
    }
    ctx.restore();
  }

  artMonkey(ctx, fur = "#8a5732", accent = "#5ad0ff", angle = 0) {
    // Body.
    ctx.fillStyle = fur;
    ctx.strokeStyle = "rgba(45,24,10,.45)";
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.ellipse(0, 5, 12.5, 13, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    // Ears.
    for (const s of [-1, 1]) {
      ctx.fillStyle = fur;
      ctx.beginPath();
      ctx.arc(s * 11, -9, 4.2, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = "#e8b986";
      ctx.beginPath();
      ctx.arc(s * 11, -9, 2.3, 0, Math.PI * 2);
      ctx.fill();
    }

    // Head.
    ctx.fillStyle = fur;
    ctx.beginPath();
    ctx.arc(0, -8, 11.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    // Face.
    ctx.fillStyle = "#f0c68e";
    ctx.beginPath();
    ctx.ellipse(0, -6.2, 7.6, 7.8, 0, 0, Math.PI * 2);
    ctx.fill();

    // Eyes.
    const lookX = Math.cos(angle) * 1.5;
    const lookY = Math.sin(angle) * 1.2;
    for (const s of [-1, 1]) {
      ctx.fillStyle = "#fffaf0";
      ctx.beginPath();
      ctx.arc(s * 3.4, -9.2, 2.6, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = "#202018";
      ctx.beginPath();
      ctx.arc(s * 3.4 + lookX, -9.2 + lookY, 1.35, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = "rgba(255,255,255,.9)";
      ctx.beginPath();
      ctx.arc(s * 3.4 + lookX - 0.5, -9.2 + lookY - 0.6, 0.45, 0, Math.PI * 2);
      ctx.fill();
    }

    // Nostrils + smile.
    ctx.fillStyle = "rgba(110,65,30,.55)";
    ctx.beginPath();
    ctx.arc(-1.3, -5, 0.7, 0, Math.PI * 2);
    ctx.arc(1.3, -5, 0.7, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = "rgba(90,50,20,.7)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(0, -3.4, 2.6, 0.25, Math.PI - 0.25);
    ctx.stroke();

    // Headband.
    ctx.fillStyle = accent;
    ctx.beginPath();
    ctx.roundRect(-11, -16, 22, 4.4, 2);
    ctx.fill();
    ctx.strokeStyle = "rgba(20,40,60,.5)";
    ctx.lineWidth = 0.8;
    ctx.stroke();
    // Band tails.
    ctx.fillStyle = accent;
    ctx.beginPath();
    ctx.moveTo(10, -15);
    ctx.lineTo(18, -13);
    ctx.lineTo(10, -11);
    ctx.closePath();
    ctx.fill();
  }

  armAndDart(ctx, angle, color = "#d8dde6") {
    ctx.save();
    ctx.rotate(angle);
    // Arm.
    ctx.fillStyle = "#8a5732";
    ctx.beginPath();
    ctx.ellipse(10, 0, 6, 4.5, 0, 0, Math.PI * 2);
    ctx.fill();
    // Dart.
    ctx.fillStyle = "#7d5a34";
    ctx.beginPath();
    ctx.roundRect(12, -1.6, 17, 3.2, 1.4);
    ctx.fill();
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(29, -3.2);
    ctx.lineTo(36, 0);
    ctx.lineTo(29, 3.2);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = "#ff6b6b";
    ctx.beginPath();
    ctx.moveTo(13, -1.6);
    ctx.lineTo(18, -5);
    ctx.lineTo(19, -1.6);
    ctx.closePath();
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(13, 1.6);
    ctx.lineTo(18, 5);
    ctx.lineTo(19, 1.6);
    ctx.closePath();
    ctx.fill();
    // Hand.
    ctx.fillStyle = "#e8b986";
    ctx.beginPath();
    ctx.arc(13.5, 0, 3, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  artDart(ctx, angle, flash) {
    this.artMonkey(ctx, "#8a5732", "#5ad0ff", angle);
    this.armAndDart(ctx, angle);
    if (flash) this.muzzle(ctx, angle, 34, "#b8f0ff");
  }

  artTack(ctx, time, flash, level) {
    ctx.save();
    ctx.rotate(time * 0.35);
    // Spikes.
    const count = 8 + level * 2;
    for (let i = 0; i < count; i++) {
      const a = (i / count) * Math.PI * 2;
      ctx.save();
      ctx.rotate(a);
      ctx.fillStyle = "#c9d2dd";
      ctx.beginPath();
      ctx.moveTo(14, -3.2);
      ctx.lineTo(26, 0);
      ctx.lineTo(14, 3.2);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = "rgba(60,70,84,.6)";
      ctx.lineWidth = 0.8;
      ctx.stroke();
      ctx.restore();
    }
    // Disc.
    ctx.fillStyle = "#3f4854";
    ctx.beginPath();
    ctx.arc(0, 0, 15.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = "#222a33";
    ctx.lineWidth = 1.6;
    ctx.stroke();
    ctx.fillStyle = "#596676";
    ctx.beginPath();
    ctx.arc(-3, -4, 12, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#ffcf5c";
    ctx.beginPath();
    ctx.arc(0, 0, 4, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = "#8e6514";
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.restore();
    if (flash) {
      ctx.fillStyle = "rgba(255,220,150,.28)";
      ctx.beginPath();
      ctx.arc(0, 0, 25, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  artBoomerang(ctx, angle, time, flash) {
    this.artMonkey(ctx, "#a0683a", "#ffd35c", angle);
    ctx.save();
    ctx.rotate(angle);
    // Hand + boomerang.
    ctx.fillStyle = "#e8b986";
    ctx.beginPath();
    ctx.arc(13, 0, 3.4, 0, Math.PI * 2);
    ctx.fill();
    ctx.translate(24, 0);
    ctx.rotate(time * 1.5);
    ctx.strokeStyle = "#e9b64a";
    ctx.lineWidth = 6;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.moveTo(-7, -7);
    ctx.quadraticCurveTo(4, 0, -7, 7);
    ctx.stroke();
    ctx.strokeStyle = "rgba(120,75,15,.55)";
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(-7, -7);
    ctx.quadraticCurveTo(4, 0, -7, 7);
    ctx.stroke();
    ctx.restore();
    if (flash) this.muzzle(ctx, angle, 30, "#ffe9a8");
  }

  artBomb(ctx, angle, flash) {
    // Wheels.
    for (const s of [-1, 1]) {
      ctx.fillStyle = "#2c3138";
      ctx.beginPath();
      ctx.arc(s * 9, 8, 6, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = "#7a8494";
      ctx.beginPath();
      ctx.arc(s * 9, 8, 2.4, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.save();
    ctx.rotate(angle);
    // Barrel.
    const g = ctx.createLinearGradient(0, -8, 0, 8);
    g.addColorStop(0, "#5c6674");
    g.addColorStop(0.5, "#333b46");
    g.addColorStop(1, "#1b2129");
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.roundRect(-8, -8, 34, 16, 6);
    ctx.fill();
    ctx.strokeStyle = "#141920";
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.fillStyle = "#d65252";
    ctx.fillRect(18, -8, 4, 16);
    ctx.fillStyle = "#262c35";
    ctx.beginPath();
    ctx.ellipse(26, 0, 4, 8, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#596270";
    ctx.beginPath();
    ctx.ellipse(0, 0, 8, 9, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
    // Fuse.
    ctx.strokeStyle = "#a9906b";
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(-8, -4);
    ctx.quadraticCurveTo(-16, -10, -18, -3);
    ctx.stroke();
    if (flash) this.muzzle(ctx, angle, 28, "#ffb45c");
  }

  artIce(ctx, time, level) {
    const pulse = 0.5 + Math.sin(time * 3) * 0.2;
    ctx.fillStyle = "rgba(155,231,255,0.16)";
    ctx.beginPath();
    ctx.arc(0, 0, 21, 0, Math.PI * 2);
    ctx.fill();
    // Snow mound.
    ctx.fillStyle = "#eaf9ff";
    ctx.beginPath();
    ctx.ellipse(0, 7, 17, 9, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "rgba(150,210,235,.45)";
    ctx.beginPath();
    ctx.ellipse(7, 9, 8, 4, 0, 0, Math.PI * 2);
    ctx.fill();
    // Crystals.
    const crystals = [
      [0, -16, 9, 22, "#bff2ff"],
      [-10, -9, 5, 13, "#8fdcf7"],
      [10, -8, 5, 14, "#a9e8ff"],
    ];
    for (const [cx, cy, w, h, col] of crystals) {
      ctx.fillStyle = col;
      ctx.beginPath();
      ctx.moveTo(cx, cy - h / 2);
      ctx.lineTo(cx + w / 2, cy + h / 2);
      ctx.lineTo(cx, cy + h / 2 - 3);
      ctx.lineTo(cx - w / 2, cy + h / 2);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = "rgba(70,150,190,.5)";
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.fillStyle = "rgba(255,255,255,.7)";
      ctx.beginPath();
      ctx.moveTo(cx, cy - h / 2 + 2);
      ctx.lineTo(cx - 1.5, cy + 2);
      ctx.lineTo(cx + 1.5, cy + 1);
      ctx.closePath();
      ctx.fill();
    }
    ctx.fillStyle = `rgba(190,245,255,${0.1 + pulse * 0.15})`;
    ctx.beginPath();
    ctx.arc(0, -4, 18, 0, Math.PI * 2);
    ctx.fill();
  }

  artSniper(ctx, angle, flash) {
    this.artMonkey(ctx, "#6f7a42", "#9fe870", angle);
    // Cap.
    ctx.fillStyle = "#4d5c2d";
    ctx.beginPath();
    ctx.ellipse(0, -16, 10.5, 5, 0, Math.PI, Math.PI * 2);
    ctx.fill();
    ctx.fillRect(-10.5, -16, 21, 2.2);
    ctx.fillStyle = "#39461f";
    ctx.beginPath();
    ctx.ellipse(4, -14, 9, 2.4, 0.08, 0, Math.PI * 2);
    ctx.fill();
    // Rifle.
    ctx.save();
    ctx.rotate(angle);
    ctx.fillStyle = "#6e4a28";
    ctx.beginPath();
    ctx.roundRect(4, -2.4, 14, 5, 2);
    ctx.fill();
    ctx.fillStyle = "#2f343c";
    ctx.beginPath();
    ctx.roundRect(16, -2, 22, 3.6, 1.5);
    ctx.fill();
    ctx.fillStyle = "#1e2228";
    ctx.beginPath();
    ctx.roundRect(14, -4.5, 7, 2.5, 1);
    ctx.fill();
    ctx.fillStyle = "#8fe0ff";
    ctx.beginPath();
    ctx.arc(18, -4.2, 1.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
    if (flash) this.muzzle(ctx, angle, 39, "#ffd98a");
  }

  artNinja(ctx, angle, time, level) {
    // Scarf.
    ctx.strokeStyle = "#d24b4b";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(3, -8);
    ctx.quadraticCurveTo(-12 - Math.sin(time * 4) * 3, -2, -20 - Math.sin(time * 4) * 4, 4);
    ctx.stroke();
    ctx.fillStyle = "#4a3f6e";
    ctx.beginPath();
    ctx.ellipse(0, 4, 12.5, 13, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = "#2b2442";
    ctx.lineWidth = 1.4;
    ctx.stroke();
    // Head.
    ctx.fillStyle = "#332c4d";
    ctx.beginPath();
    ctx.arc(0, -8, 11.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    // Mask.
    ctx.fillStyle = "#221d35";
    ctx.beginPath();
    ctx.ellipse(0, -6, 9.5, 7, 0, 0, Math.PI * 2);
    ctx.fill();
    // Eyes.
    for (const s of [-1, 1]) {
      ctx.fillStyle = "#ff8d6e";
      ctx.beginPath();
      ctx.ellipse(s * 4, -9, 2.4, 1.5, s * 0.15, 0, Math.PI * 2);
      ctx.fill();
    }
    // Headband knot.
    ctx.fillStyle = "#d24b4b";
    ctx.fillRect(-11, -15.5, 22, 2.4);
    // Shuriken.
    ctx.save();
    ctx.rotate(angle);
    ctx.translate(15, 0);
    ctx.rotate(time * 6);
    ctx.fillStyle = "#c9d2dd";
    for (let i = 0; i < 4; i++) {
      ctx.rotate(Math.PI / 2);
      ctx.beginPath();
      ctx.moveTo(0, -8);
      ctx.lineTo(2.6, -2.4);
      ctx.lineTo(0, 0);
      ctx.lineTo(-2.6, -2.4);
      ctx.closePath();
      ctx.fill();
    }
    ctx.fillStyle = "#59636f";
    ctx.beginPath();
    ctx.arc(0, 0, 1.8, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
    if (level >= 3) {
      ctx.save();
      ctx.rotate(angle + Math.PI);
      ctx.translate(15, 0);
      ctx.rotate(-time * 6);
      ctx.fillStyle = "#c9d2dd";
      for (let i = 0; i < 4; i++) {
        ctx.rotate(Math.PI / 2);
        ctx.beginPath();
        ctx.moveTo(0, -8);
        ctx.lineTo(2.6, -2.4);
        ctx.lineTo(0, 0);
        ctx.lineTo(-2.6, -2.4);
        ctx.closePath();
        ctx.fill();
      }
      ctx.restore();
    }
  }

  artWizard(ctx, angle, time, level) {
    // Robe.
    ctx.fillStyle = "#5f3f92";
    ctx.beginPath();
    ctx.moveTo(-13, 14);
    ctx.lineTo(-7, -8);
    ctx.lineTo(7, -8);
    ctx.lineTo(13, 14);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "#3a245c";
    ctx.lineWidth = 1.4;
    ctx.stroke();
    // Stars on robe.
    ctx.fillStyle = "rgba(255,214,92,.8)";
    for (const [sx, sy] of [[-5, 5], [4, 8], [0, 0]]) {
      this.drawStar(ctx, sx, sy, 2.2, 4);
    }
    // Face.
    ctx.fillStyle = "#f0c68e";
    ctx.beginPath();
    ctx.arc(0, -12, 8.5, 0, Math.PI * 2);
    ctx.fill();
    // Beard.
    ctx.fillStyle = "#e8e4d8";
    ctx.beginPath();
    ctx.moveTo(-7, -9);
    ctx.quadraticCurveTo(0, 2, 7, -9);
    ctx.quadraticCurveTo(4, -3, 0, -4);
    ctx.quadraticCurveTo(-4, -3, -7, -9);
    ctx.fill();
    // Eyes.
    for (const s of [-1, 1]) {
      ctx.fillStyle = "#2a2340";
      ctx.beginPath();
      ctx.arc(s * 3, -13, 1.4, 0, Math.PI * 2);
      ctx.fill();
    }
    // Hat.
    ctx.fillStyle = "#4d3278";
    ctx.beginPath();
    ctx.moveTo(-12, -18);
    ctx.lineTo(0, -40);
    ctx.lineTo(12, -18);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "#2f1d4c";
    ctx.lineWidth = 1.4;
    ctx.stroke();
    ctx.fillStyle = "#3a2560";
    ctx.beginPath();
    ctx.ellipse(0, -18, 15, 3.6, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#ffcf5c";
    this.drawStar(ctx, 0, -28, 2.4, 4.5);
    if (level >= 1) this.drawStar(ctx, 7, -21, 1.5, 3);
    // Staff with orb.
    ctx.save();
    ctx.rotate(angle);
    ctx.strokeStyle = "#7a5835";
    ctx.lineWidth = 2.6;
    ctx.beginPath();
    ctx.moveTo(6, 4);
    ctx.lineTo(26, 0);
    ctx.stroke();
    const glow = 0.6 + Math.sin(time * 4) * 0.25;
    ctx.fillStyle = `rgba(199,139,255,${glow})`;
    ctx.beginPath();
    ctx.arc(28, 0, 5, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "rgba(255,255,255,.85)";
    ctx.beginPath();
    ctx.arc(26.7, -1.5, 1.6, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  artSuper(ctx, angle, time, level) {
    // Cape.
    ctx.fillStyle = "#d63d4b";
    ctx.beginPath();
    ctx.moveTo(-2, -16);
    ctx.quadraticCurveTo(-24 - Math.sin(time * 3) * 3, 0, -20 - Math.sin(time * 3) * 4, 20);
    ctx.lineTo(3, 14);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "rgba(110,20,30,.5)";
    ctx.lineWidth = 1;
    ctx.stroke();
    // Suit.
    ctx.fillStyle = "#2f6cc4";
    ctx.beginPath();
    ctx.ellipse(0, 4, 12.5, 13, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#ffcf5c";
    ctx.beginPath();
    ctx.moveTo(-5, -2);
    ctx.lineTo(0, 6);
    ctx.lineTo(5, -2);
    ctx.lineTo(0, 0);
    ctx.closePath();
    ctx.fill();
    // Head (monkey).
    ctx.fillStyle = "#8a5732";
    ctx.beginPath();
    ctx.arc(0, -9, 11, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#f0c68e";
    ctx.beginPath();
    ctx.ellipse(0, -7, 7.4, 7.4, 0, 0, Math.PI * 2);
    ctx.fill();
    // Mask.
    ctx.fillStyle = "#2f6cc4";
    ctx.beginPath();
    ctx.roundRect(-10, -17, 20, 6, 3);
    ctx.fill();
    // Glowing eyes.
    const glow = 0.7 + Math.sin(time * 6) * 0.2;
    for (const s of [-1, 1]) {
      ctx.fillStyle = `rgba(255,235,120,${glow})`;
      ctx.beginPath();
      ctx.ellipse(s * 3.3, -9.6, 2.4, 1.6, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = "rgba(255,255,255,.9)";
      ctx.beginPath();
      ctx.arc(s * 3.3, -9.8, 0.7, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.save();
    ctx.rotate(angle);
    ctx.fillStyle = "#ffcf5c";
    ctx.beginPath();
    ctx.arc(14, 0, 3.4, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
    // Level aura.
    if (level >= 3) {
      ctx.strokeStyle = `rgba(255,220,100,${0.35 + Math.sin(time * 5) * 0.15})`;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(0, 0, 22, 0, Math.PI * 2);
      ctx.stroke();
    }
  }

  drawStar(ctx, x, y, inner, outer, points = 5) {
    ctx.beginPath();
    for (let i = 0; i < points * 2; i++) {
      const r = i % 2 ? inner : outer;
      const a = (i / (points * 2)) * Math.PI * 2 - Math.PI / 2;
      ctx.lineTo(x + Math.cos(a) * r, y + Math.sin(a) * r);
    }
    ctx.closePath();
    ctx.fill();
  }

  muzzle(ctx, angle, dist, color) {
    ctx.save();
    ctx.rotate(angle);
    const g = ctx.createRadialGradient(dist, 0, 1, dist, 0, 14);
    g.addColorStop(0, "rgba(255,255,255,.95)");
    g.addColorStop(0.35, hexA(color, 0.8));
    g.addColorStop(1, "rgba(255,200,80,0)");
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(dist, 0, 14, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  // ---------------------------------------------------------------- projectiles & fx

  drawProjectile(ctx, p, time) {
    if (p.kind === "bomb") {
      const pos = bombPos(p);
      ctx.save();
      ctx.translate(pos.x, pos.y);
      ctx.fillStyle = "rgba(20,40,16,.22)";
      ctx.beginPath();
      ctx.ellipse(0, p.arcHeight + 8, 5, 2.4, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.rotate(p.spin);
      ctx.fillStyle = "#232a33";
      ctx.beginPath();
      ctx.arc(0, 0, 5.2, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = "#586375";
      ctx.beginPath();
      ctx.arc(-1.4, -1.6, 1.6, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = "#b8996a";
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(3, -3.5);
      ctx.quadraticCurveTo(7, -7, 4, -9);
      ctx.stroke();
      ctx.fillStyle = "#ffd45c";
      ctx.beginPath();
      ctx.arc(4, -9.5, 1.6 + Math.sin(time * 20) * 0.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
      return;
    }

    ctx.save();
    ctx.translate(p.x, p.y);
    const ang = Math.atan2(p.vy, p.vx);

    if (p.kind === "dart") {
      ctx.rotate(ang);
      ctx.fillStyle = "#6f4e2c";
      ctx.beginPath();
      ctx.roundRect(-8, -1.4, 13, 2.8, 1);
      ctx.fill();
      ctx.fillStyle = "#e8edf4";
      ctx.beginPath();
      ctx.moveTo(5, -2.6);
      ctx.lineTo(10, 0);
      ctx.lineTo(5, 2.6);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = "#5ac8ff";
      ctx.beginPath();
      ctx.moveTo(-8, -1.4);
      ctx.lineTo(-11, -3.8);
      ctx.lineTo(-6, -1.4);
      ctx.closePath();
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(-8, 1.4);
      ctx.lineTo(-11, 3.8);
      ctx.lineTo(-6, 1.4);
      ctx.closePath();
      ctx.fill();
    } else if (p.kind === "tack") {
      ctx.rotate(p.spin || ang);
      ctx.fillStyle = "#c2cbd6";
      ctx.beginPath();
      ctx.moveTo(0, -5.5);
      ctx.lineTo(1.8, 2);
      ctx.lineTo(-1.8, 2);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = "rgba(60,70,84,.7)";
      ctx.lineWidth = 0.7;
      ctx.stroke();
    } else if (p.kind === "boomerang") {
      ctx.rotate(p.spin);
      ctx.strokeStyle = "#e8b64a";
      ctx.lineWidth = 4.6;
      ctx.lineCap = "round";
      ctx.beginPath();
      ctx.moveTo(-7, -6);
      ctx.quadraticCurveTo(4, 0, -7, 6);
      ctx.stroke();
      ctx.strokeStyle = "rgba(110,70,15,.6)";
      ctx.lineWidth = 1.1;
      ctx.beginPath();
      ctx.moveTo(-7, -6);
      ctx.quadraticCurveTo(4, 0, -7, 6);
      ctx.stroke();
    } else if (p.kind === "magic") {
      const g = ctx.createRadialGradient(0, 0, 1, 0, 0, 9);
      g.addColorStop(0, "#ffffff");
      g.addColorStop(0.3, "#d9a6ff");
      g.addColorStop(1, "rgba(160,80,255,0)");
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(0, 0, 9, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = "#b96bff";
      ctx.beginPath();
      ctx.arc(0, 0, 3.4, 0, Math.PI * 2);
      ctx.fill();
    } else if (p.kind === "laser") {
      ctx.rotate(ang);
      const g = ctx.createLinearGradient(-16, 0, 8, 0);
      g.addColorStop(0, "rgba(255,220,80,0)");
      g.addColorStop(0.5, "#ffe066");
      g.addColorStop(1, "#fffbe0");
      ctx.strokeStyle = g;
      ctx.lineWidth = 3.2;
      ctx.lineCap = "round";
      ctx.beginPath();
      ctx.moveTo(-15, 0);
      ctx.lineTo(8, 0);
      ctx.stroke();
    } else {
      ctx.fillStyle = "#fff";
      ctx.beginPath();
      ctx.arc(0, 0, 3, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }

  drawEffects(ctx, game, time) {
    for (const e of game.effects) {
      if (e.kind === "ring") {
        const f = 1 - e.life / e.maxLife;
        const r = e.r0 + (e.r1 - e.r0) * easeOut(f);
        ctx.strokeStyle = hexA(e.color, (1 - f) * 0.8);
        ctx.lineWidth = e.width * (1 - f * 0.6);
        ctx.beginPath();
        ctx.arc(e.x, e.y, r, 0, Math.PI * 2);
        ctx.stroke();
        if (e.fill) {
          ctx.fillStyle = hexA(e.color, (1 - f) * 0.12);
          ctx.beginPath();
          ctx.arc(e.x, e.y, r, 0, Math.PI * 2);
          ctx.fill();
        }
      } else if (e.kind === "explosion") {
        const f = 1 - e.life / e.maxLife;
        const r = e.r * easeOut(f);
        const g = ctx.createRadialGradient(e.x, e.y, 1, e.x, e.y, Math.max(2, r));
        g.addColorStop(0, `rgba(255,255,220,${(1 - f) * 0.9})`);
        g.addColorStop(0.4, `rgba(255,180,60,${(1 - f) * 0.5})`);
        g.addColorStop(1, "rgba(255,90,30,0)");
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(e.x, e.y, Math.max(2, r), 0, Math.PI * 2);
        ctx.fill();
      } else if (e.kind === "tracer") {
        const a = Math.max(0, e.life / e.maxLife);
        ctx.strokeStyle = `rgba(255, 240, 170, ${a * 0.9})`;
        ctx.lineWidth = 2.2;
        ctx.beginPath();
        ctx.moveTo(e.x1, e.y1);
        ctx.lineTo(e.x2, e.y2);
        ctx.stroke();
        ctx.strokeStyle = `rgba(255, 255, 255, ${a * 0.7})`;
        ctx.lineWidth = 0.9;
        ctx.stroke();
      } else if (e.kind === "text") {
        // handled in texts
      }
    }
    // Ice frost sparkles around chilled bloons.
    for (const b of game.balloons) {
      if (b.slowTimer > 0 && b.type !== "moab") {
        for (let i = 0; i < 2; i++) {
          const a = time * 2 + b.phase + i * 2.4;
          ctx.fillStyle = "rgba(220,250,255,.55)";
          ctx.beginPath();
          ctx.arc(b.x + Math.cos(a) * 12, b.y + Math.sin(a) * 16, 1.4, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    }
  }

  drawParticle(ctx, p) {
    const f = Math.max(0, p.life / p.maxLife);
    ctx.globalAlpha = Math.min(1, f * 1.6);
    ctx.fillStyle = p.color;
    if (p.shape === "spark") {
      ctx.fillRect(p.x - p.size / 2, p.y - p.size / 2, p.size, p.size);
    } else {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * (0.4 + f * 0.6), 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  drawText(ctx, t) {
    const f = Math.max(0, t.life / t.maxLife);
    ctx.save();
    ctx.globalAlpha = Math.min(1, f * 1.8);
    ctx.font = t.big ? "900 20px 'Trebuchet MS', sans-serif" : "800 13px 'Trebuchet MS', sans-serif";
    ctx.textAlign = "center";
    ctx.lineWidth = 3;
    ctx.strokeStyle = "rgba(20,30,15,.65)";
    const y = t.y - (1 - f) * 26;
    ctx.strokeText(t.text, t.x, y);
    ctx.fillStyle = t.color;
    ctx.fillText(t.text, t.x, y);
    ctx.restore();
  }
}

function bombPos(p) {
  const f = p.t;
  const x = p.sx + (p.tx - p.sx) * f;
  const y = p.sy + (p.ty - p.sy) * f;
  return { x, y: y - Math.sin(f * Math.PI) * p.arcHeight };
}

export { bombPos };

function easeOut(t) {
  return 1 - Math.pow(1 - t, 3);
}

function hexA(hex, a) {
  if (hex.startsWith("rgba")) return hex;
  const h = hex.replace("#", "");
  const n = h.length === 3 ? h.split("").map((c) => c + c).join("") : h;
  const r = parseInt(n.slice(0, 2), 16);
  const g = parseInt(n.slice(2, 4), 16);
  const b = parseInt(n.slice(4, 6), 16);
  return `rgba(${r},${g},${b},${a})`;
}

// Game simulation: waves, towers, bloons, projectiles, economy.

import {
  W, H, BLOONS, TOWER_BY_ID, towerStats, buildWave, roundBonus,
  START_CASH, START_LIVES, MAX_ROUND, TARGET_MODES,
} from "./config.js";

let nextEntityId = 1;

export class Game {
  constructor(track, blockers) {
    this.track = track;
    this.blockers = blockers;
    this.onEvent = () => {};
    this.pointer = null;
    this.placing = null;
    this.placementValid = false;
    this.reset();
  }

  reset() {
    this.cash = START_CASH;
    this.lives = START_LIVES;
    this.round = 1;
    this.bestRound = Number(localStorage.getItem("bloonPatrolBest") || 0);
    this.balloons = [];
    this.towers = [];
    this.projectiles = [];
    this.particles = [];
    this.effects = [];
    this.texts = [];
    this.selected = null;
    this.placing = null;
    this.pointer = null;
    this.placementValid = false;
    this.roundActive = false;
    this.spawnQueue = [];
    this.spawnIndex = 0;
    this.spawnClock = 0;
    this.totalInWave = 0;
    this.aliveSpawned = 0;
    this.autoStart = false;
    this.autoTimer = 0;
    this.started = false;
    this.paused = false;
    this.over = false;
    this.victory = false;
    this.speed = 1;
    this.time = 0;
    this.shake = 0;
    this.damageFlash = 0;
    this.popped = 0;
    this.cashEarned = 0;
    this.leaked = 0;
    this.roundsCleared = 0;
    this.pendingRoundClear = false;
  }

  emit(name, data = {}) {
    this.onEvent(name, data);
  }

  startGame() {
    if (this.started) return;
    this.started = true;
    this.paused = false;
    this.emit("start");
  }

  // ------------------------------------------------------------- placement

  placementInfo(typeId, x, y) {
    const def = TOWER_BY_ID[typeId];
    if (!def) return { valid: false, reason: "Unknown tower" };
    if (x < 28 || x > W - 28 || y < 30 || y > H - 20) return { valid: false, reason: "Off the field" };
    if (this.track.distanceTo(x, y) < 48) return { valid: false, reason: "Can't build on the track" };
    for (const t of this.towers) {
      if (Math.hypot(t.x - x, t.y - y) < 44) return { valid: false, reason: "Too close to another tower" };
    }
    for (const d of this.blockers) {
      if (Math.hypot(d.x - x, d.y - y) < d.r + 15) return { valid: false, reason: "Blocked by scenery" };
    }
    if (this.cash < def.cost) return { valid: false, reason: "Not enough cash" };
    return { valid: true, reason: "" };
  }

  setPointer(pos) {
    this.pointer = pos;
    if (pos && this.placing) {
      const info = this.placementInfo(this.placing, pos.x, pos.y);
      this.placementValid = info.valid;
    }
  }

  armTower(typeId) {
    if (this.selected) this.selected = null;
    this.placing = this.placing === typeId ? null : typeId;
    if (this.placing) {
      const def = TOWER_BY_ID[typeId];
      if (this.cash < def.cost) {
        this.placing = null;
        this.emit("error", { message: "Not enough cash for " + def.name });
        return;
      }
      this.emit("arm", { typeId });
    }
  }

  disarmTower() {
    this.placing = null;
    this.placementValid = false;
  }

  tryPlaceAt(x, y) {
    if (!this.placing) return false;
    const typeId = this.placing;
    const def = TOWER_BY_ID[typeId];
    const info = this.placementInfo(typeId, x, y);
    if (!info.valid) {
      this.emit("error", { message: info.reason });
      this.emit("bad");
      return false;
    }
    this.cash -= def.cost;
    const stats = towerStats(def, 0);
    const tower = {
      id: nextEntityId++,
      def,
      x, y,
      level: 0,
      stats,
      angle: -Math.PI / 2,
      cooldown: 0.3,
      flash: 0,
      targetMode: "first",
      spent: def.cost,
      kills: 0,
      damageDealt: 0,
      shots: 0,
    };
    this.towers.push(tower);
    this.selected = tower;
    this.placing = null;
    this.placementValid = false;
    this.emit("place", { tower });
    return true;
  }

  selectAt(x, y) {
    for (let i = this.towers.length - 1; i >= 0; i--) {
      const t = this.towers[i];
      if (Math.hypot(t.x - x, t.y - y) < 27) {
        this.selected = t;
        this.placing = null;
        this.emit("select", { tower: t });
        return true;
      }
    }
    if (this.selected) {
      this.selected = null;
      this.emit("deselect");
    }
    return false;
  }

  selectTower(tower) {
    this.selected = tower;
    this.placing = null;
    this.emit("select", { tower });
  }

  cycleTarget() {
    const t = this.selected;
    if (!t) return;
    const i = TARGET_MODES.indexOf(t.targetMode);
    t.targetMode = TARGET_MODES[(i + 1) % TARGET_MODES.length];
    this.emit("target", { tower: t });
  }

  upgradeSelected() {
    const t = this.selected;
    if (!t) return false;
    const def = t.def;
    if (t.level >= def.upgrades.length) return false;
    const up = def.upgrades[t.level];
    if (this.cash < up.cost) {
      this.emit("error", { message: "Need $" + up.cost + " for " + up.name });
      this.emit("bad");
      return false;
    }
    this.cash -= up.cost;
    t.spent += up.cost;
    t.level++;
    t.stats = towerStats(def, t.level);
    this.emit("upgrade", { tower: t, upgrade: up });
    return true;
  }

  sellSelected() {
    const t = this.selected;
    if (!t) return false;
    const refund = Math.floor(t.spent * 0.8);
    this.cash += refund;
    this.towers = this.towers.filter((x) => x !== t);
    this.selected = null;
    this.emit("sell", { refund, tower: t });
    return true;
  }

  // ------------------------------------------------------------- waves

  startRound() {
    if (!this.started || this.over || this.victory) return false;
    if (this.roundActive || this.round > MAX_ROUND) return false;
    this.spawnQueue = buildWave(this.round);
    this.spawnIndex = 0;
    this.spawnClock = 0;
    this.totalInWave = this.spawnQueue.length;
    this.roundActive = true;
    this.autoTimer = 0;
    this.emit("waveStart", { round: this.round, count: this.totalInWave });
    return true;
  }

  finishRound() {
    this.roundActive = false;
    this.roundsCleared++;
    if (this.round > this.bestRound) {
      this.bestRound = this.round;
      try { localStorage.setItem("bloonPatrolBest", String(this.bestRound)); } catch {}
    }
    const bonus = roundBonus(this.round);
    this.cash += bonus;
    this.cashEarned += bonus;
    this.emit("roundClear", { round: this.round, bonus });
    this.round++;
    if (this.round > MAX_ROUND) {
      this.victory = true;
      this.emit("victory");

      return;
    }
    if (this.autoStart) this.autoTimer = 4.5;
  }

  gameOver() {
    this.over = true;
    this.roundActive = false;
    this.placing = null;
    this.selected = null;
    if (this.round > this.bestRound) {
      this.bestRound = this.round;
      try { localStorage.setItem("bloonPatrolBest", String(this.bestRound)); } catch {}
    }
    this.emit("gameover");
  }

  // ------------------------------------------------------------- update

  update(rawDt) {
    if (!this.started || this.paused || this.over || this.victory) {
      this.updateVisuals(rawDt);
      return;
    }
    const dt = Math.min(0.05, rawDt);
    this.time += dt;

    if (this.shake > 0) this.shake = Math.max(0, this.shake - dt * 30);
    if (this.damageFlash > 0) this.damageFlash = Math.max(0, this.damageFlash - dt * 2.2);

    if (this.roundActive) {
      this.spawnClock += dt;
      while (this.spawnIndex < this.spawnQueue.length && this.spawnQueue[this.spawnIndex].time <= this.spawnClock) {
        this.spawnBloon(this.spawnQueue[this.spawnIndex].type);
        this.spawnIndex++;
      }
    } else if (this.autoStart && this.autoTimer > 0) {
      this.autoTimer -= dt;
      if (this.autoTimer <= 0) this.startRound();
    }

    this.updateBalloons(dt);
    this.updateTowers(dt);
    this.updateProjectiles(dt);
    this.updateVisuals(dt);

    if (this.roundActive && this.spawnIndex >= this.spawnQueue.length && this.balloons.length === 0) {
      this.finishRound();
    }
  }

  updateVisuals(dt) {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += p.gravity * dt;
      p.vx *= 0.985;
      if (p.life <= 0) this.particles.splice(i, 1);
    }
    for (let i = this.effects.length - 1; i >= 0; i--) {
      const e = this.effects[i];
      e.life -= dt;
      if (e.life <= 0) this.effects.splice(i, 1);
    }
    for (let i = this.texts.length - 1; i >= 0; i--) {
      const t = this.texts[i];
      t.life -= dt;
      if (t.life <= 0) this.texts.splice(i, 1);
    }
  }

  spawnBloon(type, distance = 0, sideOffset = 0) {
    const def = BLOONS[type];
    const d = Math.max(0, Math.min(this.track.length - 1, distance));
    const p = this.track.pointAt(d);
    const n = this.track.normalAt(d);
    const hpScale = type === "moab" ? 1 + Math.max(0, this.round - 25) * 0.075 : 1;
    const hp = Math.max(1, Math.round(def.hp * hpScale));
    const b = {
      id: nextEntityId++,
      type,
      def,
      hp,
      maxHp: hp,
      distance: d,
      radius: def.radius,
      phase: Math.random() * Math.PI * 2,
      slowFactor: 1,
      slowTimer: 0,
      hitFlash: 0,
      x: p.x + n.x * sideOffset,
      y: p.y + n.y * sideOffset,
      sideOffset,
      heading: 0,
      dead: false,
    };
    const tan = this.track.tangentAt(d);
    b.heading = Math.atan2(tan.y, tan.x);
    this.balloons.push(b);
    if (type === "moab") this.emit("moab");
    return b;
  }

  updateBalloons(dt) {
    const len = this.track.length;
    for (let i = this.balloons.length - 1; i >= 0; i--) {
      const b = this.balloons[i];
      if (b.dead) { this.balloons.splice(i, 1); continue; }
      if (b.hitFlash > 0) b.hitFlash = Math.max(0, b.hitFlash - dt * 4);
      if (b.slowTimer > 0) {
        b.slowTimer -= dt;
        if (b.slowTimer <= 0) { b.slowTimer = 0; b.slowFactor = 1; }
      }
      const speed = b.def.speed * (b.slowFactor || 1);
      b.distance += speed * dt;
      if (b.distance >= len) {
        this.balloons.splice(i, 1);
        this.lives -= b.def.leak;
        this.leaked++;
        this.damageFlash = 1;
        this.shake = Math.min(12, 5 + b.def.leak);
        this.addText(`-${b.def.leak}`, b.x, b.y - 20, "#ff8b92", true);
        this.emit("leak", { balloon: b });
        if (this.lives <= 0) {
          this.lives = 0;
          this.gameOver();
          return;
        }
        continue;
      }
      const p = this.track.pointAt(b.distance);
      const n = this.track.normalAt(b.distance);
      b.x = p.x + n.x * (b.sideOffset || 0);
      b.y = p.y + n.y * (b.sideOffset || 0);
      const tan = this.track.tangentAt(b.distance);
      b.heading = Math.atan2(tan.y, tan.x);
      // Children wobble back toward the center line.
      if (b.sideOffset) b.sideOffset *= 1 - Math.min(1, dt * 0.7);
    }
  }

  updateTowers(dt) {
    for (const t of this.towers) {
      if (t.flash > 0) t.flash = Math.max(0, t.flash - dt);
      t.cooldown = Math.max(0, t.cooldown - dt);
      const target = this.findTarget(t);
      if (target) {
        const want = Math.atan2(target.y - t.y, target.x - t.x);
        let diff = want - t.angle;
        while (diff > Math.PI) diff -= Math.PI * 2;
        while (diff < -Math.PI) diff += Math.PI * 2;
        t.angle += diff * Math.min(1, dt * 14);
        if (t.cooldown <= 0) this.fire(t, target);
      }
    }
  }

  findTarget(t) {
    let best = null;
    let bestScore = -Infinity;
    const range = t.stats.range;
    for (const b of this.balloons) {
      if (b.dead) continue;
      if (!t.stats.global) {
        const reach = range + b.radius;
        if ((b.x - t.x) ** 2 + (b.y - t.y) ** 2 > reach * reach) continue;
      }
      let score;
      switch (t.targetMode) {
        case "last": score = -b.distance; break;
        case "close": score = -Math.hypot(b.x - t.x, b.y - t.y); break;
        case "strong": score = b.hp * 100000 + b.distance; break;
        default: score = b.distance; break;
      }
      if (score > bestScore) { bestScore = score; best = b; }
    }
    return best;
  }

  fire(t, target) {
    const s = t.stats;
    const def = t.def;
    t.flash = 0.1;
    t.cooldown = s.cooldown;
    t.shots++;

    if (s.pulse) {
      this.effects.push({ kind: "ring", x: t.x, y: t.y, r0: 12, r1: s.range, life: 0.5, maxLife: 0.5, color: "#a8ecff", width: 9, fill: true });
      let hit = false;
      for (const b of this.balloons) {
        if (b.dead) continue;
        if (Math.hypot(b.x - t.x, b.y - t.y) > s.range + b.radius) continue;
        hit = true;
        b.slowFactor = Math.min(b.slowFactor || 1, 1 - s.slow);
        b.slowTimer = Math.max(b.slowTimer, s.slowDur);
        this.damageBalloon(b, s.damage, t);
      }
      if (hit) this.emit("ice");
      return;
    }

    if (s.hitscan) {
      let victims = [target];
      if (s.pierce > 1) {
        victims = this.balloons
          .filter((b) => !b.dead && b !== target)
          .sort((a, b) => Math.abs(a.distance - target.distance) - Math.abs(b.distance - target.distance))
          .slice(0, Math.max(0, s.pierce - 1))
          .concat([target]);
      }
      for (const b of victims) {
        this.effects.push({ kind: "tracer", x1: t.x, y1: t.y - 8, x2: b.x, y2: b.y, life: 0.18, maxLife: 0.18 });
        this.damageBalloon(b, s.damage, t);
        this.burst(b.x, b.y, b.def.color, 4, 8);
      }
      this.emit("sniper");
      return;
    }

    if (s.radial) {
      const count = s.count;
      for (let i = 0; i < count; i++) {
        const a = (i / count) * Math.PI * 2 + this.time * 0.3;
        this.projectiles.push({
          kind: "tack",
          x: t.x, y: t.y,
          vx: Math.cos(a) * s.speed,
          vy: Math.sin(a) * s.speed,
          speed: s.speed,
          damage: s.damage,
          pierce: s.pierce,
          life: s.life ?? 0.25,
          maxLife: s.life ?? 0.25,
          r: 4,
          spin: Math.random() * 6,
          owner: t,
          hits: new Set(),
        });
      }
      this.emit("shoot", { kind: "tack" });
      return;
    }

    // Predicted aim point.
    let aim = { x: target.x, y: target.y };
    if (s.bomb) {
      const dist = Math.hypot(target.x - t.x, target.y - t.y);
      const travel = dist / s.speed;
      const pred = this.track.pointAt(Math.min(this.track.length, target.distance + target.def.speed * (target.slowFactor || 1) * travel));
      aim = pred;
      const duration = Math.max(0.25, dist / s.speed);
      for (let i = 0; i < s.count; i++) {
        const spread = (i - (s.count - 1) / 2) * 26;
        const p = this.track.pointAt(Math.max(0, Math.min(this.track.length, target.distance + target.def.speed * (target.slowFactor || 1) * travel + spread)));
        this.projectiles.push({
          kind: "bomb",
          sx: t.x, sy: t.y - 6,
          x: t.x, y: t.y - 6,
          tx: p.x + (Math.random() - 0.5) * 10,
          ty: p.y + (Math.random() - 0.5) * 10,
          t: 0,
          duration: Math.max(0.2, duration + (Math.random() - 0.5) * 0.08),
          arcHeight: Math.max(30, Math.min(105, dist * 0.3)),
          damage: s.damage,
          splash: s.splash,
          spin: Math.random() * 6,
          owner: t,
        });
      }
      this.emit("shoot", { kind: "bomb" });
      return;
    }

    // Dart-like / magic / laser / boomerang.
    const travel = Math.hypot(aim.x - t.x, aim.y - t.y) / Math.max(1, s.speed);
    const future = this.track.pointAt(Math.min(this.track.length, target.distance + target.def.speed * (target.slowFactor || 1) * travel));
    let baseAngle = Math.atan2(future.y - t.y, future.x - t.x);
    if (s.boomerang) baseAngle = Math.atan2(target.y - t.y, target.x - t.x);

    const count = s.count || 1;
    for (let i = 0; i < count; i++) {
      const spread = count > 1 ? (i - (count - 1) / 2) * (s.radial ? 0 : 0.11) : 0;
      const a = baseAngle + spread;
      const kind = s.boomerang ? "boomerang" : s.laser ? "laser" : s.magic ? "magic" : "dart";
      this.projectiles.push({
        kind,
        x: t.x + Math.cos(a) * 14,
        y: t.y + Math.sin(a) * 14 - 4,
        vx: Math.cos(a) * s.speed,
        vy: Math.sin(a) * s.speed,
        speed: s.speed,
        damage: s.damage,
        pierce: s.pierce,
        splash: s.splash || 0,
        life: s.boomerang ? 3.5 : 2.2,
        maxLife: 3.5,
        r: 5,
        spin: 0,
        owner: t,
        hits: new Set(),
        boomerang: !!s.boomerang,
        returning: false,
        outTime: 0,
        turnTime: s.boomerang ? 0.42 : 0,
        hitCooldowns: s.boomerang ? new Map() : null,
      });
    }
    this.emit("shoot", { kind: s.boomerang ? "boomerang" : s.laser ? "laser" : s.magic ? "magic" : "dart" });
  }

  updateProjectiles(dt) {
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      if (p.kind === "bomb") {
        p.t += dt / p.duration;
        const f = Math.min(1, p.t);
        p.x = p.sx + (p.tx - p.sx) * f;
        p.y = p.sy + (p.ty - p.sy) * f;
        p.spin += dt * 9;
        if (p.t >= 1) {
          this.explode(p);
          this.projectiles.splice(i, 1);
        }
        continue;
      }

      p.life -= dt;

      if (p.boomerang) {
        p.outTime += dt;
        if (!p.returning) {
          p.x += p.vx * dt;
          p.y += p.vy * dt;
          if (p.outTime >= p.turnTime) p.returning = true;
        } else {
          const dx = p.owner.x - p.x;
          const dy = p.owner.y - p.y;
          const d = Math.hypot(dx, dy);
          if (d < 16) {
            this.projectiles.splice(i, 1);
            continue;
          }
          p.x += (dx / d) * p.speed * 1.25 * dt;
          p.y += (dy / d) * p.speed * 1.25 * dt;
        }
        p.spin = (p.spin || 0) + dt * 18;
      } else {
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.spin = (p.spin || 0) + dt * 8;
      }

      if (p.life <= 0 || p.x < -40 || p.x > W + 40 || p.y < -40 || p.y > H + 40) {
        this.projectiles.splice(i, 1);
        continue;
      }

      // Collisions.
      let consumed = false;
      for (const b of this.balloons) {
        if (b.dead) continue;
        if (p.boomerang) {
          const last = p.hitCooldowns.get(b.id) ?? -1;
          if (this.time - last < 0.28) continue;
        } else if (p.hits.has(b.id)) continue;
        const reach = b.radius + p.r;
        if ((b.x - p.x) ** 2 + (b.y - p.y) ** 2 > reach * reach) continue;

        if (p.splash) {
          this.explodeAt(b.x, b.y, p.splash, p.damage, p.owner, "magic");
          this.projectiles.splice(i, 1);
          consumed = true;
          break;
        }

        this.damageBalloon(b, p.damage, p.owner);
        this.burst(b.x, b.y, b.def.color, 3, 6);
        if (p.boomerang) {
          p.hitCooldowns.set(b.id, this.time);
        } else {
          p.hits.add(b.id);
          p.pierce--;
          if (p.pierce <= 0) {
            this.projectiles.splice(i, 1);
            consumed = true;
            break;
          }
        }
      }
      if (consumed) continue;
    }
  }

  explode(p) {
    this.explodeAt(p.x, p.y, p.splash, p.damage, p.owner, "bomb");
  }

  explodeAt(x, y, radius, damage, owner, flavor = "bomb") {
    this.effects.push({ kind: "explosion", x, y, r: radius * 1.15, life: 0.34, maxLife: 0.34 });
    this.effects.push({ kind: "ring", x, y, r0: radius * 0.2, r1: radius, life: 0.3, maxLife: 0.3, color: flavor === "magic" ? "#d8a6ff" : "#ffb463", width: 4 });
    for (const b of this.balloons) {
      if (b.dead) continue;
      if (Math.hypot(b.x - x, b.y - y) > radius + b.radius) continue;
      this.damageBalloon(b, damage, owner);
    }
    this.burst(x, y, flavor === "magic" ? "#d9a6ff" : "#ffb45c", 10, 20);
    this.shake = Math.max(this.shake, 3);
    this.emit(flavor === "magic" ? "magicBoom" : "boom");
  }

  damageBalloon(b, dmg, owner) {
    if (b.dead || b.hp <= 0) return;
    b.hp -= dmg;
    b.hitFlash = 0.16;
    if (owner) owner.damageDealt += dmg;
    if (b.hp > 0) {
      this.burst(b.x, b.y, b.def.accent, 2, 4);
      return;
    }
    b.dead = true;
    if (owner) owner.kills++;
    this.popped++;
    const bounty = b.def.bounty;
    this.cash += bounty;
    this.cashEarned += bounty;
    const idx = this.balloons.indexOf(b);
    if (idx >= 0) this.balloons.splice(idx, 1);

    this.burst(b.x, b.y, b.def.color, b.def.big ? 34 : 8, b.def.big ? 42 : 12);
    if (b.def.big) {
      this.shake = 9;
      this.effects.push({ kind: "explosion", x: b.x, y: b.y, r: 90, life: 0.5, maxLife: 0.5 });
      this.emit("moabPop");
    }
    if (bounty >= 8 || Math.random() < 0.3) {
      this.addText(`+$${bounty}`, b.x, b.y - b.radius - 4, "#ffd866");
    }
    this.emit("pop", { type: b.type, big: b.def.big });

    if (b.def.children.length) {
      const kids = b.def.children;
      const spread = b.def.big ? 30 : 9;
      for (let i = 0; i < kids.length; i++) {
        const off = kids.length === 1 ? 0 : (i - (kids.length - 1) / 2) * spread;
        const child = this.spawnBloon(kids[i], b.distance + (i - (kids.length - 1) / 2) * 4, off + (Math.random() - 0.5) * 5);
        child.phase = Math.random() * Math.PI * 2;
      }
    }
  }

  // ------------------------------------------------------------- fx helpers

  burst(x, y, color, count = 8, speed = 12) {
    if (this.particles.length > 650) return;
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2;
      const sp = speed * (0.35 + Math.random() * 0.9);
      this.particles.push({
        x, y,
        vx: Math.cos(a) * sp * 6,
        vy: Math.sin(a) * sp * 6 - 20,
        gravity: 380,
        life: 0.35 + Math.random() * 0.4,
        maxLife: 0.75,
        size: 1.8 + Math.random() * 3.2,
        color,
        shape: Math.random() < 0.2 ? "spark" : "dot",
      });
    }
  }

  addText(text, x, y, color = "#ffe9af", big = false) {
    if (this.texts.length > 45) this.texts.shift();
    this.texts.push({ text, x, y, color, big, life: 1.0, maxLife: 1.0 });
  }

  // ------------------------------------------------------------- UI helpers

  towerPreviewStats(t) {
    const s = t.stats;
    return {
      damage: s.damage,
      range: s.range > 3000 ? "∞" : Math.round(s.range),
      rate: s.cooldown > 0 ? `${(1 / s.cooldown).toFixed(1)}/s` : "—",
      pierce: s.pierce >= 90 ? "AoE" : s.pierce,
      count: s.count || 1,
    };
  }

  waveProgress() {
    if (!this.roundActive) return 0;
    const spawned = this.spawnIndex;
    const total = Math.max(1, this.totalInWave);
    return Math.min(1, spawned / total);
  }
}

// DOM UI: HUD, armory cards, tower inspector, overlays, toasts.

import { TOWERS, TOWER_BY_ID, TARGET_LABEL, MAX_ROUND } from "./config.js";

export class UI {
  constructor(game, renderer, hooks = {}) {
    this.game = game;
    this.renderer = renderer;
    this.hooks = hooks;
    this.cache = {};
    this.inspectorSig = "";
    this.toastTimer = null;
    this.overlayMode = null;
    this.helpWasPaused = false;

    this.el = {
      lives: document.getElementById("hud-lives"),
      cash: document.getElementById("hud-cash"),
      round: document.getElementById("hud-round"),
      speed: document.getElementById("btn-speed"),
      pause: document.getElementById("btn-pause"),
      sound: document.getElementById("btn-sound"),
      help: document.getElementById("btn-help"),
      roundLabel: document.getElementById("round-label"),
      progress: document.getElementById("round-progress"),
      auto: document.getElementById("auto-start"),
      start: document.getElementById("btn-start"),
      shop: document.getElementById("shop"),
      inspector: document.getElementById("inspector"),
      overlay: document.getElementById("overlay"),
      toast: document.getElementById("toast"),
      hint: document.getElementById("place-hint"),
    };

    this.buildShop();
    this.bind();
  }

  // ------------------------------------------------------------- build

  buildShop() {
    const wrap = this.el.shop;
    wrap.innerHTML = "";
    TOWERS.forEach((def, i) => {
      const card = document.createElement("button");
      card.className = "tower-card";
      card.dataset.tower = def.id;
      card.style.animationDelay = `${i * 30}ms`;
      const cv = document.createElement("canvas");
      cv.width = 84;
      cv.height = 84;
      cv.setAttribute("aria-hidden", "true");
      const ctx = cv.getContext("2d");
      ctx.scale(2, 2);
      ctx.translate(42, 44);
      this.renderer.drawTowerBody(ctx, def.id, 0, -Math.PI / 2 + 0.2, 0.6, 0, 0, 1.02);
      card.appendChild(cv);
      const body = document.createElement("div");
      body.className = "tc-body";
      const name = document.createElement("div");
      name.className = "tc-name";
      name.textContent = def.name;
      const price = document.createElement("div");
      price.className = "price";
      price.textContent = String(def.cost);
      body.appendChild(name);
      body.appendChild(price);
      card.appendChild(body);
      const key = document.createElement("span");
      key.className = "key";
      key.textContent = String(i + 1);
      card.appendChild(key);
      card.title = `${def.name} — $${def.cost}\n${def.blurb}`;
      card.addEventListener("click", () => {
        this.game.armTower(def.id);
        this.game.emit("ui");
      });
      wrap.appendChild(card);
    });
  }

  bind() {
    this.el.start.addEventListener("click", () => {
      if (!this.game.started) this.game.startGame();
      this.game.startRound();
      this.game.emit("ui");
    });

    this.el.auto.addEventListener("change", () => {
      this.game.autoStart = this.el.auto.checked;
      if (this.game.autoStart && this.game.started && !this.game.roundActive && !this.game.over && !this.game.victory) {
        this.game.autoTimer = Math.max(this.game.autoTimer, 2.4);
      }
    });

    this.el.speed.addEventListener("click", () => {
      const next = this.game.speed === 1 ? 2 : this.game.speed === 2 ? 3 : 1;
      this.game.speed = next;
      this.game.emit("ui");
    });

    this.el.pause.addEventListener("click", () => this.togglePause());
    this.el.sound.addEventListener("click", () => this.hooks.onSound?.());
    this.el.help.addEventListener("click", () => this.showHelp());

    this.el.inspector.addEventListener("click", (e) => {
      const action = e.target.closest("[data-action]")?.dataset.action;
      if (action === "close") {
        this.game.selected = null;
        this.game.emit("deselect");
      } else if (action === "target") {
        this.game.cycleTarget();
      } else if (action === "upgrade") {
        this.game.upgradeSelected();
      } else if (action === "sell") {
        this.game.sellSelected();
      }
    });

    this.el.overlay.addEventListener("click", (e) => {
      const action = e.target.closest("[data-action]")?.dataset.action;
      if (!action) return;
      if (action === "play") {
        this.hideOverlay();
        this.game.startGame();
        this.game.emit("ui");
        this.hooks.onUnlock?.();
      } else if (action === "help") {
        this.showHelp();
      } else if (action === "resume") {
        this.hideOverlay();
        this.game.paused = false;
        this.game.emit("ui");
      } else if (action === "restart") {
        this.hideOverlay();
        this.hooks.onRestart?.();
      } else if (action === "close-help") {
        this.hideOverlay();
        if (!this.helpWasPaused) this.game.paused = false;
        this.helpWasPaused = false;
        this.game.emit("ui");
      } else if (action === "close-help-paused") {
        this.hideOverlay();
        this.game.emit("ui");
      } else if (action === "resume-help") {
        this.hideOverlay();
        this.game.paused = false;
        this.game.emit("ui");
      }
    });
  }

  // ------------------------------------------------------------- overlays

  showOverlay(html, mode) {
    this.overlayMode = mode;
    this.el.overlay.innerHTML = html;
    this.el.overlay.classList.remove("hidden");
  }

  hideOverlay() {
    this.overlayMode = null;
    this.el.overlay.classList.add("hidden");
    this.el.overlay.innerHTML = "";
  }

  get overlayOpen() {
    return this.overlayMode !== null;
  }

  togglePause() {
    if (!this.game.started || this.game.over || this.game.victory) return;
    if (this.overlayOpen) {
      if (this.overlayMode === "pause") {
        this.hideOverlay();
        this.game.paused = false;
      }
      return;
    }
    if (this.game.paused) {
      this.game.paused = false;
      this.el.pause.classList.remove("on");
    } else {
      this.game.paused = true;
      this.el.pause.classList.add("on");
      this.showPause();
    }
    this.game.emit("ui");
  }

  showIntro() {
    const best = this.game.bestRound > 0 ? `<p class="lede" style="margin-top:14px;color:#ffcf5c;font-weight:800;font-size:12px">Your best: wave ${this.game.bestRound}</p>` : "";
    this.showOverlay(`
      <div class="panel">
        <p class="eyebrow">Sunny Meadow · 40 waves</p>
        <h2>They float.<br><span class="accent">They pop.</span></h2>
        <p class="lede">A parade of balloons is heading for the village. Build a ridiculous army of monkeys, wizards and war machines to stop every last one.</p>
        ${best}
        <div class="how">
          <div><b>1 · Build</b>Pick a tower from the armory, then tap the grass to place it.</div>
          <div><b>2 · Pop</b>Bloons split into smaller, faster bloons. Pop those too.</div>
          <div><b>3 · Upgrade</b>Tap any tower for three tiers of upgrades and targeting.</div>
          <div><b>4 · Survive</b>Leaks cost lives. Clear all 40 waves to win the meadow.</div>
        </div>
        <button class="big-btn" data-action="play">
          <svg viewBox="0 0 24 24"><path d="M8 5.5v13l10-6.5z" fill="currentColor"/></svg>
          Start Defending
        </button>
      </div>
    `, "intro");
  }

  showHelp() {
    if (this.overlayMode === "help") return;
    this.helpWasPaused = this.game.paused;
    if (this.game.started && !this.game.over && !this.game.victory) this.game.paused = true;
    const inGame = this.game.started && !this.game.over && !this.game.victory;
    this.showOverlay(`
      <div class="panel">
        <p class="eyebrow">Field Manual</p>
        <h2>How to play</h2>
        <p class="lede">Every bloon that reaches the gate costs lives. Keep the track covered and upgrade early — later waves get spicy.</p>
        <div class="how">
          <div><b>Placement</b>Towers can't sit on the dirt track or on trees and rocks.</div>
          <div><b>Targeting</b>First, Last, Closest or Strongest. Snipers hit anywhere.</div>
          <div><b>Money</b>Every pop pays. Clear a wave for a cash bonus. Sell for 80% back.</div>
          <div><b>Speed</b>1× / 2× / 3× with F. Pause with P. Mute with M.</div>
          <div><b>Hotkeys</b>1–9 select towers. Esc cancels. S sells. U upgrades.</div>
          <div><b>Bosses</b>MOAB blimps arrive from wave 25. They hit hard and split.</div>
        </div>
        <button class="big-btn" data-action="${inGame ? "close-help" : "play"}">${inGame ? "Back to the meadow" : "Start Defending"}</button>
      </div>
    `, "help");
  }

  showPause() {
    this.showOverlay(`
      <div class="panel">
        <p class="eyebrow">Take a breath</p>
        <h2>Paused</h2>
        <p class="lede">The bloons are politely waiting. Upgrade something while you're here.</p>
        <button class="big-btn" data-action="resume">Resume</button>
        <button class="ghost-btn" data-action="restart">Restart Run</button>
      </div>
    `, "pause");
  }

  showGameOver() {
    const g = this.game;
    this.showOverlay(`
      <div class="panel">
        <p class="eyebrow">Defeat</p>
        <h2>The bloons<br><span class="accent">got through.</span></h2>
        <p class="lede">The meadow needs a better plan. Try a tighter bend, more upgrades, or a wall of ice.</p>
        <div class="result-stats">
          <div class="result-stat"><span>Wave</span><b>${Math.min(g.round, MAX_ROUND)}</b></div>
          <div class="result-stat"><span>Bloons popped</span><b>${g.popped}</b></div>
          <div class="result-stat"><span>Best</span><b>${g.bestRound}</b></div>
        </div>
        <button class="big-btn" data-action="restart">Try Again</button>
      </div>
    `, "gameover");
  }

  showVictory() {
    const g = this.game;
    this.showOverlay(`
      <div class="panel">
        <p class="eyebrow">Victory · 40 / 40 waves</p>
        <h2>Meadow<br><span class="accent">secured.</span></h2>
        <p class="lede">Every last bloon has been popped. The village is safe, the monkeys are celebrating, and the grass will never be the same.</p>
        <div class="result-stats">
          <div class="result-stat"><span>Lives left</span><b>${g.lives}</b></div>
          <div class="result-stat"><span>Popped</span><b>${g.popped}</b></div>
          <div class="result-stat"><span>Earned</span><b>$${g.cashEarned}</b></div>
        </div>
        <button class="big-btn" data-action="restart">Play Again</button>
      </div>
    `, "victory");
  }

  // ------------------------------------------------------------- per-frame

  sync() {
    const g = this.game;
    if (this.cache.lives !== g.lives) {
      this.el.lives.textContent = g.lives;
      this.cache.lives = g.lives;
    }
    if (this.cache.cash !== g.cash) {
      this.el.cash.textContent = g.cash;
      this.cache.cash = g.cash;
    }
    if (this.cache.round !== g.round) {
      this.el.round.textContent = Math.min(g.round, MAX_ROUND);
      this.cache.round = g.round;
    }

    const speedLabel = g.speed + "×";
    if (this.cache.speed !== speedLabel) {
      this.el.speed.textContent = speedLabel;
      this.el.speed.classList.toggle("on", g.speed > 1);
      this.cache.speed = speedLabel;
    }

    // Start button.
    let startHTML;
    let disabled = false;
    if (g.roundActive) {
      startHTML = `<svg viewBox="0 0 24 24"><path d="M8 5.5v13l10-6.5z" fill="currentColor"/></svg><span>Wave in Progress</span>`;
      disabled = true;
    } else if (g.round > MAX_ROUND) {
      startHTML = `<span>All Waves Cleared</span>`;
      disabled = true;
    } else {
      startHTML = `<svg viewBox="0 0 24 24"><path d="M8 5.5v13l10-6.5z" fill="currentColor"/></svg><span>Start Wave ${g.round}</span>`;
    }
    const startSig = startHTML + (disabled ? "1" : "0");
    if (this.cache.start !== startSig) {
      this.el.start.innerHTML = startHTML;
      this.el.start.disabled = disabled;
      this.el.start.classList.toggle("pulse", !disabled && !g.roundActive && g.started && !this.overlayOpen);
      this.cache.start = startSig;
    }

    const label = g.roundActive
      ? `Wave ${g.round} · ${g.balloons.length + (g.spawnQueue.length - g.spawnIndex)} left`
      : g.started
        ? `Wave ${Math.min(g.round, MAX_ROUND)} / ${MAX_ROUND}`
        : "Get ready";
    if (this.cache.label !== label) {
      this.el.roundLabel.textContent = label;
      this.cache.label = label;
    }
    const prog = g.roundActive ? `${Math.round(g.waveProgress() * 100)}%` : "0%";
    if (this.cache.prog !== prog) {
      this.el.progress.style.width = prog;
      this.cache.prog = prog;
    }

    if (this.cache.auto !== g.autoStart) {
      this.el.auto.checked = g.autoStart;
      this.cache.auto = g.autoStart;
    }

    // Shop affordability + selection.
    const cards = this.el.shop.children;
    for (const card of cards) {
      const def = TOWER_BY_ID[card.dataset.tower];
      const poor = g.cash < def.cost;
      if (card.classList.contains("poor") !== poor) card.classList.toggle("poor", poor);
      const sel = g.placing === def.id;
      if (card.classList.contains("selected") !== sel) card.classList.toggle("selected", sel);
    }

    // Placement hint.
    if (g.placing) {
      const def = TOWER_BY_ID[g.placing];
      const text = `Placing ${def.name} · $${def.cost} — tap the grass · Esc to cancel`;
      if (this.el.hint.textContent !== text) this.el.hint.textContent = text;
      this.el.hint.classList.remove("hidden");
    } else if (!this.el.hint.classList.contains("hidden")) {
      this.el.hint.classList.add("hidden");
    }

    // Pause button state.
    const paused = g.paused;
    if (this.cache.paused !== paused) {
      this.el.pause.classList.toggle("on", paused);
      this.el.pause.innerHTML = paused
        ? `<svg viewBox="0 0 24 24"><path d="M8 5.5v13l10-6.5z" fill="currentColor"/></svg>`
        : `<svg viewBox="0 0 24 24"><rect x="6" y="4" width="4" height="16" rx="1.2" fill="currentColor"/><rect x="14" y="4" width="4" height="16" rx="1.2" fill="currentColor"/></svg>`;
      this.cache.paused = paused;
    }

    this.syncInspector();
  }

  syncInspector() {
    const g = this.game;
    const t = g.selected;
    if (!t) {
      if (this.cache.inspecting) {
        this.el.inspector.classList.add("hidden");
        this.el.inspector.innerHTML = "";
        this.inspectorSig = "";
        this.cache.inspecting = false;
      }
      return;
    }
    this.cache.inspecting = true;
    const sig = `${t.id}:${t.level}:${t.targetMode}`;
    if (sig !== this.inspectorSig) {
      this.inspectorSig = sig;
      this.el.inspector.classList.remove("hidden");
      this.el.inspector.innerHTML = this.inspectorHTML(t);
      const cv = this.el.inspector.querySelector("canvas");
      if (cv) {
        const ctx = cv.getContext("2d");
        ctx.scale(2, 2);
        ctx.translate(44, 46);
        this.renderer.drawTowerBody(ctx, t.def.id, t.level, -Math.PI / 2 + 0.2, 0.6, 0, 0, 1.02);
      }
    }
    // Live affordability / refund.
    const upBtn = this.el.inspector.querySelector('[data-action="upgrade"]');
    if (upBtn) {
      const next = t.def.upgrades[t.level];
      const poor = g.cash < next.cost;
      if (upBtn.disabled !== poor) upBtn.disabled = poor;
      const cost = upBtn.querySelector(".cost");
      if (cost) cost.textContent = "$" + next.cost;
    }
    const sell = this.el.inspector.querySelector('[data-action="sell"] .val');
    if (sell) {
      const val = "$" + Math.floor(t.spent * 0.8);
      if (sell.textContent !== val) sell.textContent = val;
    }
  }

  inspectorHTML(t) {
    const s = t.stats;
    const up = t.def.upgrades[t.level];
    const refund = Math.floor(t.spent * 0.8);
    const stats = `
      <div class="ins-stats">
        <div class="ins-stat"><span>Damage</span><b>${fmt(s.damage)}</b></div>
        <div class="ins-stat"><span>Range</span><b>${s.range > 3000 ? "∞" : Math.round(s.range)}</b></div>
        <div class="ins-stat"><span>Rate</span><b>${(1 / s.cooldown).toFixed(1)}/s</b></div>
      </div>`;
    let upgradeArea;
    if (up) {
      upgradeArea = `
        <button class="ins-upgrade" data-action="upgrade" ${this.game.cash < up.cost ? "disabled" : ""}>
          <span class="plus">+</span>
          <span class="txt"><b>${up.name}</b><span>Tier ${t.level + 1} · ${up.desc}</span></span>
          <span class="cost">$${up.cost}</span>
        </button>`;
    } else {
      upgradeArea = `<div class="ins-maxed">★ Fully Upgraded ★</div>`;
    }
    return `
      <div class="ins-head">
        <canvas class="ins-icon" width="88" height="88"></canvas>
        <div class="ins-title">
          <h3>${t.def.name}</h3>
          <p>Tier ${t.level}${t.level >= 3 ? " · Max" : ""} · ${t.kills} pops</p>
        </div>
        <button class="ins-close" data-action="close" aria-label="Close">×</button>
      </div>
      ${stats}
      <button class="ins-target" data-action="target">Targeting <em>${TARGET_LABEL[t.targetMode]} ⇄</em></button>
      ${upgradeArea}
      <div class="ins-foot">
        <button class="ins-sell" data-action="sell">Sell <span class="val">$${refund}</span></button>
      </div>
    `;
  }

  // ------------------------------------------------------------- toast

  toast(message, kind = "", duration = 2000) {
    const el = this.el.toast;
    el.textContent = message;
    el.className = "toast show " + kind;
    clearTimeout(this.toastTimer);
    this.toastTimer = setTimeout(() => {
      el.classList.remove("show");
    }, duration);
  }
}

function fmt(n) {
  return Number.isInteger(n) ? n : n.toFixed(1);
}

// Bootstrap: renderer, game, UI, input and main loop.

import { W, H, MAP, TOWERS, BLOONS } from "./config.js";
import { Track } from "./path.js";
import { Renderer } from "./render.js";
import { Game } from "./game.js";
import { UI } from "./ui.js";
import { AudioKit } from "./audio.js";

const canvas = document.getElementById("game");
const track = new Track(MAP.waypoints, 30);
const renderer = new Renderer(canvas, track, MAP.pathWidth);
const game = new Game(track, renderer.blockers);
const audio = new AudioKit();

let muted = false;
try { muted = localStorage.getItem("bloonPatrolMute") === "1"; } catch {}

const ui = new UI(game, renderer, {
  onRestart: () => restartRun(),
  onSound: () => toggleSound(),
  onUnlock: () => audio.unlock(),
});

if (muted) {
  audio.enabled = false;
  ui.el.sound.classList.add("off");
  ui.el.sound.title = "Sound off";
}

const shootThrottle = new Map();

game.onEvent = (name, data = {}) => {
  switch (name) {
    case "place":
      audio.place();
      break;
    case "upgrade":
      audio.upgrade();
      ui.toast(`${data.upgrade.name} unlocked!`, "good", 1500);
      break;
    case "sell":
      audio.sell();
      ui.toast(`Sold for $${data.refund}`, "", 1300);
      break;
    case "error":
      audio.error();
      ui.toast(data.message || "Can't do that", "bad", 1700);
      break;
    case "bad":
      break;
    case "waveStart":
      audio.waveStart();
      ui.toast(`Wave ${data.round} incoming — ${data.count} bloons`, "", 1900);
      break;
    case "roundClear":
      audio.roundClear();
      ui.toast(`Wave ${data.round} cleared · +$${data.bonus}`, "good", 2300);
      game.addText(`Wave Clear +$${data.bonus}`, W / 2, H * 0.32, "#ffe9a1", true);
      break;
    case "leak":
      audio.leak();
      if (data.balloon?.def.big) ui.toast(`MOAB leaked! -${data.balloon.def.leak} lives`, "bad", 1800);
      break;
    case "gameover":
      audio.lose();
      setTimeout(() => ui.showGameOver(), 700);
      break;
    case "victory":
      audio.win();
      setTimeout(() => ui.showVictory(), 700);
      break;
    case "pop": {
      const r = BLOONS[data.type]?.radius || 14;
      audio.pop(r);
      break;
    }
    case "moabPop":
      audio.boom();
      ui.toast("MOAB popped!", "good", 1500);
      break;
    case "moab":
      audio.moab();
      ui.toast("MOAB detected — focus fire!", "bad", 2200);
      break;
    case "boom":
    case "magicBoom":
      audio.boom();
      break;
    case "ice":
      audio.ice();
      break;
    case "sniper":
      audio.shoot("sniper");
      break;
    case "shoot": {
      const kind = data.kind || "dart";
      const now = performance.now();
      const last = shootThrottle.get(kind) || 0;
      if (now - last > 55) {
        shootThrottle.set(kind, now);
        audio.shoot(kind);
      }
      break;
    }
    default:
      break;
  }
};

function toggleSound() {
  muted = !muted;
  audio.unlock();
  audio.setEnabled(!muted);
  ui.el.sound.classList.toggle("off", muted);
  ui.el.sound.title = muted ? "Sound off" : "Sound on";
  try { localStorage.setItem("bloonPatrolMute", muted ? "1" : "0"); } catch {}
  if (!muted) audio.tone({ freq: 660, end: 880, dur: 0.12, type: "triangle", vol: 0.08 });
}

function restartRun() {
  game.reset();
  game.started = true;
  game.paused = false;
  ui.hideOverlay();
  ui.cache = {};
  ui.inspectorSig = "";
  ui.el.pause.classList.remove("on");
  ui.toast("Fresh start — place your towers", "good", 2000);
  audio.place();
}

// ---------------------------------------------------------------- input

function toWorld(e) {
  const rect = canvas.getBoundingClientRect();
  return {
    x: ((e.clientX - rect.left) / rect.width) * W,
    y: ((e.clientY - rect.top) / rect.height) * H,
  };
}

canvas.addEventListener("pointerdown", (e) => {
  e.preventDefault();
  audio.unlock();
  if (ui.overlayOpen) return;
  if (!game.started || game.over || game.victory) return;
  const p = toWorld(e);
  if (game.placing) {
    game.setPointer(p);
    const ok = game.tryPlaceAt(p.x, p.y);
    if (!ok) game.emit("ui");
    return;
  }
  game.selectAt(p.x, p.y);
  game.emit("ui");
});

canvas.addEventListener("pointermove", (e) => {
  if (e.pointerType === "touch") return;
  const p = toWorld(e);
  game.setPointer(p);
  canvas.style.cursor = game.placing ? (game.placementValid ? "copy" : "not-allowed") : "crosshair";
});

canvas.addEventListener("pointerleave", () => {
  game.setPointer(null);
});

canvas.addEventListener("contextmenu", (e) => {
  e.preventDefault();
  if (game.placing) {
    game.disarmTower();
    game.emit("ui");
  }
});

window.addEventListener("keydown", (e) => {
  if (e.target && /input|textarea|select/i.test(e.target.tagName)) return;
  audio.unlock();
  const key = e.key.toLowerCase();

  if (key === "escape") {
    if (game.placing) {
      game.disarmTower();
      game.emit("ui");
    } else if (game.selected) {
      game.selected = null;
      game.emit("deselect");
    } else if (ui.overlayMode === "pause") {
      ui.togglePause();
    }
    return;
  }

  if (ui.overlayOpen) {
    if (key === "p" && ui.overlayMode === "pause") ui.togglePause();
    return;
  }
  if (!game.started || game.over || game.victory) return;

  if (/^[1-9]$/.test(key)) {
    const def = TOWERS[Number(key) - 1];
    if (def) {
      game.armTower(def.id);
      game.emit("ui");
    }
  } else if (key === " ") {
    e.preventDefault();
    game.startRound();
  } else if (key === "p") {
    ui.togglePause();
  } else if (key === "f") {
    game.speed = game.speed === 1 ? 2 : game.speed === 2 ? 3 : 1;
    game.emit("ui");
  } else if (key === "m") {
    toggleSound();
  } else if (key === "u") {
    game.upgradeSelected();
  } else if (key === "s") {
    game.sellSelected();
  } else if (key === "a") {
    game.autoStart = !game.autoStart;
    if (game.autoStart && !game.roundActive) game.autoTimer = Math.max(game.autoTimer, 2.4);
    game.emit("ui");
  } else if (key === "enter") {
    game.startRound();
  }
});

window.addEventListener("resize", () => renderer.resize());
if (window.ResizeObserver) {
  const ro = new ResizeObserver(() => renderer.resize());
  ro.observe(canvas);
}
document.addEventListener("visibilitychange", () => {
  if (document.hidden && game.started && game.roundActive && !game.paused && !ui.overlayOpen) {
    game.paused = true;
    ui.showPause();
    ui.el.pause.classList.add("on");
  }
});

// ---------------------------------------------------------------- loop

ui.showIntro();
renderer.resize();
ui.sync();

let last = performance.now();
function frame(now) {
  const dt = Math.min(0.05, (now - last) / 1000);
  last = now;
  if (game.started && !game.paused && !game.over && !game.victory && !ui.overlayOpen) {
    game.update(dt * game.speed);
  }
  renderer.draw(game, now / 1000);
  ui.sync();
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

// Debug hook for automated checks.
window.__bloonPatrol = { game, ui, renderer, audio, track };

