  const h = Math.max(180, Math.round(rect.height * dpr));
  if (this.canvas.width !== w || this.canvas.height !== h) {
    this.canvas.width = w;
    this.canvas.height = h;
    this.cacheBackground();
  }
  this.dpr = dpr;
}

cacheBackground() {
  if (!this.bg) return;
  if (!this.bgFrame) this.bgFrame = document.createElement("canvas");
