  ctx.strokeStyle = "rgba(60,55,40,0.45)";
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(b.x + Math.sin(sway) * r * 0.3, b.y + r * 0.98);
  ctx.quadraticCurveTo(b.x + Math.sin(time * 2 + b.phase) * 5, b.y + r * 1.5, b.x + Math.sin(time * 1.5 + b.phase) * 7, b.y + r * 2.15);
  ctx.stroke();

  ctx.translate(b.x, b.y + bob);
  ctx.rotate(sway);

  // Knot.
  ctx.fillStyle = def.shade;
  ctx.beginPath();
  ctx.moveTo(-3.6, r * 0.88);
  ctx.lineTo(3.6, r * 0.88);
  ctx.lineTo(0, r * 1.14);
  ctx.closePath();
  ctx.fill();

  // Body.
  const grad = this.balloonGradient(ctx, b.type, r);
  ctx.beginPath();
  ctx.ellipse(0, 0, r * 0.9, r * 1.1, 0, 0, Math.PI * 2);
  ctx.fillStyle = grad;
  ctx.fill();

  if (def.pattern === "zebra") {
    ctx.save();
    ctx.beginPath();
    ctx.ellipse(0, 0, r * 0.9, r * 1.1, 0, 0, Math.PI * 2);
    ctx.clip();
    ctx.fillStyle = "#20242b";
    for (let i = -3; i <= 3; i++) {
      ctx.save();
      ctx.translate(i * 6.5, 0);
      ctx.rotate(0.5);
      ctx.fillRect(-2, -r * 1.4, 3.2, r * 2.8);
      ctx.restore();
    }
    ctx.restore();
  } else if (def.pattern === "rainbow") {
    ctx.save();
    ctx.beginPath();
    ctx.ellipse(0, 0, r * 0.9, r * 1.1, 0, 0, Math.PI * 2);
    ctx.clip();
    const rg = ctx.createLinearGradient(-r, -r, r, r);
    rg.addColorStop(0, "#ff5d68");
    rg.addColorStop(0.22, "#ffb84d");
    rg.addColorStop(0.44, "#ffe94d");
    rg.addColorStop(0.62, "#69e06a");
    rg.addColorStop(0.8, "#5bb8ff");
    rg.addColorStop(1, "#c07bff");
    ctx.fillStyle = rg;
    ctx.fillRect(-r, -r, r * 2, r * 2);
    ctx.restore();
  } else if (def.pattern === "ceramic") {
    ctx.save();
    ctx.beginPath();
    ctx.ellipse(0, 0, r * 0.9, r * 1.1, 0, 0, Math.PI * 2);
    ctx.clip();
    ctx.strokeStyle = "rgba(90,52,22,.5)";
    ctx.lineWidth = 1.3;
    ctx.beginPath();
    ctx.moveTo(-r * 0.6, -r * 0.6);
    ctx.lineTo(-r * 0.2, -r * 0.2);
    ctx.lineTo(-r * 0.5, r * 0.15);
    ctx.moveTo(r * 0.55, -r * 0.7);
    ctx.lineTo(r * 0.2, -r * 0.3);
    ctx.lineTo(r * 0.55, r * 0.05);
    ctx.moveTo(-r * 0.1, r * 0.5);
    ctx.lineTo(r * 0.25, r * 0.65);
    ctx.stroke();
    ctx.restore();
  }

  // Highlight.
  const hl = ctx.createRadialGradient(-r * 0.34, -r * 0.5, 0.5, -r * 0.34, -r * 0.5, r * 0.62);
  hl.addColorStop(0, "rgba(255,255,255,0.85)");
  hl.addColorStop(0.5, "rgba(255,255,255,0.22)");
  hl.addColorStop(1, "rgba(255,255,255,0)");
  ctx.fillStyle = hl;
  ctx.beginPath();
  ctx.ellipse(-r * 0.3, -r * 0.42, r * 0.4, r * 0.5, -0.5, 0, Math.PI * 2);
  ctx.fill();

  // Rim shade.
  ctx.strokeStyle = hexA(def.shade, 0.5);
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.ellipse(0, 0, r * 0.9, r * 1.1, 0, 0, Math.PI * 2);
  ctx.stroke();

  // Damage flash.
  if (b.hitFlash > 0) {
    ctx.globalAlpha = Math.min(0.85, b.hitFlash * 3);
    ctx.fillStyle = "#ffffff";
    ctx.beginPath();
    ctx.ellipse(0, 0, r * 0.9, r * 1.1, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1;
  }

  // Frozen tint.
  if (b.slowTimer > 0) {
    ctx.fillStyle = "rgba(160,235,255,0.25)";
    ctx.beginPath();
    ctx.ellipse(0, 0, r * 0.9, r * 1.1, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = "rgba(220,250,255,0.7)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-r * 0.5, -r * 0.2);
    ctx.lineTo(-r * 0.25, 0);
    ctx.lineTo(-r * 0.5, r * 0.3);
    ctx.stroke();
  }

  ctx.restore();

  if (b.maxHp > 1) this.drawHpBar(ctx, b.x, b.y - r * 1.35, r * 2.1, b.hp / b.maxHp);
}

