1: // Game simulation: waves, towers, bloons, projectiles, economy.
2: 
3: import {
4:   W, H, BLOONS, TOWER_BY_ID, towerStats, buildWave, roundBonus,
5:   START_CASH, START_LIVES, MAX_ROUND, TARGET_MODES,
6: } from "./config.js";
7: 
8: let nextEntityId = 1;
9: 
10: export class Game {
11:   constructor(track, blockers) {
12:     this.track = track;
13:     this.blockers = blockers;
14:     this.onEvent = () => {};
15:     this.pointer = null;
16:     this.placing = null;
17:     this.placementValid = false;
18:     this.reset();
19:   }
20: 
21:   reset() {
22:     this.cash = START_CASH;
23:     this.lives = START_LIVES;
24:     this.round = 1;
25:     this.bestRound = Number(localStorage.getItem("bloonPatrolBest") || 0);
26:     this.balloons = [];
27:     this.towers = [];
28:     this.projectiles = [];
29:     this.particles = [];
30:     this.effects = [];
31:     this.texts = [];
32:     this.selected = null;
33:     this.placing = null;
34:     this.pointer = null;
35:     this.placementValid = false;
36:     this.roundActive = false;
37:     this.spawnQueue = [];
38:     this.spawnIndex = 0;
39:     this.spawnClock = 0;
40:     this.totalInWave = 0;
41:     this.aliveSpawned = 0;
42:     this.autoStart = false;
43:     this.autoTimer = 0;
44:     this.started = false;
45:     this.paused = false;
46:     this.over = false;
47:     this.victory = false;
48:     this.speed = 1;
49:     this.time = 0;
50:     this.shake = 0;
51:     this.damageFlash = 0;
52:     this.popped = 0;
53:     this.cashEarned = 0;
54:     this.leaked = 0;
55:     this.roundsCleared = 0;
56:     this.pendingRoundClear = false;
57:   }
58: 
59:   emit(name, data = {}) {
60:     this.onEvent(name, data);
61:   }
62: 
63:   startGame() {
64:     if (this.started) return;
65:     this.started = true;
66:     this.paused = false;
67:     this.emit("start");
68:   }
69: 
70:   // ------------------------------------------------------------- placement
71: 
72:   placementInfo(typeId, x, y) {
73:     const def = TOWER_BY_ID[typeId];
74:     if (!def) return { valid: false, reason: "Unknown tower" };
75:     if (x < 28 || x > W - 28 || y < 30 || y > H - 20) return { valid: false, reason: "Off the field" };
76:     if (this.track.distanceTo(x, y) < 48) return { valid: false, reason: "Can't build on the track" };
77:     for (const t of this.towers) {
78:       if (Math.hypot(t.x - x, t.y - y) < 44) return { valid: false, reason: "Too close to another tower" };
79:     }
80:     for (const d of this.blockers) {
81:       if (Math.hypot(d.x - x, d.y - y) < d.r + 15) return { valid: false, reason: "Blocked by scenery" };
82:     }
83:     if (this.cash < def.cost) return { valid: false, reason: "Not enough cash" };
84:     return { valid: true, reason: "" };
85:   }
86: 
87:   setPointer(pos) {
88:     this.pointer = pos;
89:     if (pos && this.placing) {
90:       const info = this.placementInfo(this.placing, pos.x, pos.y);
91:       this.placementValid = info.valid;
92:     }
93:   }
94: 
95:   armTower(typeId) {
96:     if (this.selected) this.selected = null;
97:     this.placing = this.placing === typeId ? null : typeId;
98:     if (this.placing) {
99:       const def = TOWER_BY_ID[typeId];
100:       if (this.cash < def.cost) {
101:         this.placing = null;
102:         this.emit("error", { message: "Not enough cash for " + def.name });
103:         return;
104:       }
105:       this.emit("arm", { typeId });
106:     }
107:   }
108: 
109:   disarmTower() {
110:     this.placing = null;
111:     this.placementValid = false;
112:   }
113: 
114:   tryPlaceAt(x, y) {
115:     if (!this.placing) return false;
116:     const typeId = this.placing;
117:     const def = TOWER_BY_ID[typeId];
118:     const info = this.placementInfo(typeId, x, y);
119:     if (!info.valid) {
120:       this.emit("error", { message: info.reason });
121:       this.emit("bad");
122:       return false;
123:     }
124:     this.cash -= def.cost;
125:     const stats = towerStats(def, 0);
126:     const tower = {
127:       id: nextEntityId++,
128:       def,
129:       x, y,
130:       level: 0,
131:       stats,
132:       angle: -Math.PI / 2,
133:       cooldown: 0.3,
134:       flash: 0,
135:       targetMode: "first",
136:       spent: def.cost,
137:       kills: 0,
138:       damageDealt: 0,
139:       shots: 0,
140:     };
141:     this.towers.push(tower);
142:     this.selected = tower;
143:     this.placing = null;
144:     this.placementValid = false;
145:     this.emit("place", { tower });
146:     return true;
147:   }
148: 
149:   selectAt(x, y) {
150:     for (let i = this.towers.length - 1; i >= 0; i--) {
151:       const t = this.towers[i];
152:       if (Math.hypot(t.x - x, t.y - y) < 34) {
153:         this.selected = t;
154:         this.placing = null;
155:         this.emit("select", { tower: t });
156:         return true;
157:       }
158:     }
159:     if (this.selected) {
160:       this.selected = null;
161:       this.emit("deselect");
162:     }
163:     return false;
164:   }
165: 
166:   selectTower(tower) {
167:     this.selected = tower;
168:     this.placing = null;
169:     this.emit("select", { tower });
170:   }
171: 
172:   cycleTarget() {
173:     const t = this.selected;
174:     if (!t) return;
175:     const i = TARGET_MODES.indexOf(t.targetMode);
176:     t.targetMode = TARGET_MODES[(i + 1) % TARGET_MODES.length];
177:     this.emit("target", { tower: t });
178:   }
179: 
180:   upgradeSelected() {
181:     const t = this.selected;
182:     if (!t) return false;
183:     const def = t.def;
184:     if (t.level >= def.upgrades.length) return false;
185:     const up = def.upgrades[t.level];
186:     if (this.cash < up.cost) {
187:       this.emit("error", { message: "Need $" + up.cost + " for " + up.name });
188:       this.emit("bad");
189:       return false;
190:     }
191:     this.cash -= up.cost;
192:     t.spent += up.cost;
193:     t.level++;
194:     t.stats = towerStats(def, t.level);
195:     this.emit("upgrade", { tower: t, upgrade: up });
196:     return true;
197:   }
198: 
199:   sellSelected() {
200:     const t = this.selected;
201:     if (!t) return false;
202:     const refund = Math.floor(t.spent * 0.8);
203:     this.cash += refund;
204:     this.towers = this.towers.filter((x) => x !== t);
205:     this.selected = null;
206:     this.emit("sell", { refund, tower: t });
207:     return true;
208:   }
209: 
210:   // ------------------------------------------------------------- waves
211: 
212:   startRound() {
213:     if (!this.started || this.over || this.victory) return false;
214:     if (this.roundActive || this.round > MAX_ROUND) return false;
215:     this.spawnQueue = buildWave(this.round);
216:     this.spawnIndex = 0;
217:     this.spawnClock = 0;
218:     this.totalInWave = this.spawnQueue.length;
219:     this.roundActive = true;
220:     this.autoTimer = 0;
221:     this.emit("waveStart", { round: this.round, count: this.totalInWave });
222:     return true;
223:   }
224: 
225:   finishRound() {
226:     this.roundActive = false;
227:     this.roundsCleared++;
228:     if (this.round > this.bestRound) {
229:       this.bestRound = this.round;
230:       try { localStorage.setItem("bloonPatrolBest", String(this.bestRound)); } catch {}
231:     }
232:     const bonus = roundBonus(this.round);
233:     this.cash += bonus;
234:     this.cashEarned += bonus;
235:     this.emit("roundClear", { round: this.round, bonus });
236:     this.round++;
237:     if (this.round > MAX_ROUND) {
238:       this.victory = true;
239:       this.emit("victory");
240: 
241:       return;
242:     }
243:     if (this.autoStart) this.autoTimer = 4.5;
244:   }
245: 
246:   gameOver() {
247:     this.over = true;
248:     this.roundActive = false;
249:     this.placing = null;
250:     this.selected = null;
251:     if (this.round > this.bestRound) {
252:       this.bestRound = this.round;
253:       try { localStorage.setItem("bloonPatrolBest", String(this.bestRound)); } catch {}
254:     }
255:     this.emit("gameover");
256:   }
257: 
258:   // ------------------------------------------------------------- update
259: 
260:   update(rawDt) {
261:     if (!this.started || this.paused || this.over || this.victory) {
262:       this.updateVisuals(rawDt);
263:       return;
264:     }
265:     const dt = Math.min(0.12, rawDt);
266:     this.time += dt;
267: 
268:     if (this.shake > 0) this.shake = Math.max(0, this.shake - dt * 30);
269:     if (this.damageFlash > 0) this.damageFlash = Math.max(0, this.damageFlash - dt * 2.2);
270: 
271:     if (this.roundActive) {
272:       this.spawnClock += dt;
273:       while (this.spawnIndex < this.spawnQueue.length && this.spawnQueue[this.spawnIndex].time <= this.spawnClock) {
274:         this.spawnBloon(this.spawnQueue[this.spawnIndex].type);
275:         this.spawnIndex++;
276:       }
277:     } else if (this.autoStart && this.autoTimer > 0) {
278:       this.autoTimer -= dt;
279:       if (this.autoTimer <= 0) this.startRound();
280:     }
281: 
282:     this.updateBalloons(dt);
283:     this.updateTowers(dt);
284:     this.updateProjectiles(dt);
285:     this.updateVisuals(dt);
286: 
287:     if (this.roundActive && this.spawnIndex >= this.spawnQueue.length && this.balloons.length === 0) {
288:       this.finishRound();
289:     }
290:   }
291: 
292:   updateVisuals(dt) {
293:     for (let i = this.particles.length - 1; i >= 0; i--) {
294:       const p = this.particles[i];
295:       p.life -= dt;
296:       p.x += p.vx * dt;
297:       p.y += p.vy * dt;
298:       p.vy += p.gravity * dt;
299:       p.vx *= 0.985;
300:       if (p.life <= 0) this.particles.splice(i, 1);
301:     }
302:     for (let i = this.effects.length - 1; i >= 0; i--) {
303:       const e = this.effects[i];
304:       e.life -= dt;
305:       if (e.life <= 0) this.effects.splice(i, 1);
306:     }
307:     for (let i = this.texts.length - 1; i >= 0; i--) {
308:       const t = this.texts[i];
309:       t.life -= dt;
310:       if (t.life <= 0) this.texts.splice(i, 1);
311:     }
312:   }
313: 
314:   spawnBloon(type, distance = 0, sideOffset = 0) {
315:     const def = BLOONS[type];
316:     const d = Math.max(0, Math.min(this.track.length - 1, distance));
317:     const p = this.track.pointAt(d);
318:     const n = this.track.normalAt(d);
319:     const hpScale = type === "moab" ? 1 + Math.max(0, this.round - 25) * 0.075 : 1;
320:     const hp = Math.max(1, Math.round(def.hp * hpScale));
321:     const b = {
322:       id: nextEntityId++,
323:       type,
324:       def,
325:       hp,
326:       maxHp: hp,
327:       distance: d,
328:       radius: def.radius,
329:       phase: Math.random() * Math.PI * 2,
330:       slowFactor: 1,
331:       slowTimer: 0,
332:       hitFlash: 0,
